import{o,c as a,a2 as r,k as t,e as s,F as c,B as n}from"./chunks/framework.BaXgE4DV.js";const l=JSON.parse('[{"id":"GRATO-18","html":"<h3 id=\\"badge-celebration\\" tabindex=\\"-1\\">배지 축하 카드와 다음 배지 <a class=\\"header-anchor\\" href=\\"#badge-celebration\\" aria-label=\\"Permalink to &quot;배지 축하 카드와 다음 배지 {#badge-celebration}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>배지를 얻으면 한 번, 조용한 축하 카드가 뜸: &quot;새 배지&quot;, 아이콘, 이름·설명, 호칭이 있으면 &quot;이름 옆에 이렇게 보여요&quot; 미리보기와 <strong>이름 옆에 붙이기</strong>, 보상 공감 이모지, 다음 배지, 공유하기·닫기. 약 1.2초 연출(고리·빛줄기·입자 한 번), 움직임 줄이기에서는 페이드만, 앱은 가벼운 진동 1회 → <a href=\\"/grato-docs/features/stats-badges#celebration\\">배지 축하</a></li>\\n<li>한꺼번에 여러 개를 받으면 &quot;그동안 모은 배지 n개&quot; 한 장으로. 호칭은 가장 최근 것 하나만 바로 붙이고, 나머지는 마이페이지에서 고름</li>\\n<li>글 쓰는 중이나 다른 창 위에서는 기다렸다가 띄우고, 저절로 사라지지 않음. 같은 배지는 다른 기기에서도 다시 뜨지 않음(<code>users.badgesSeenAt</code>), 업데이트 전에 가진 배지는 축하하지 않음 → <a href=\\"/grato-docs/decisions#adr-29\\">ADR-29</a></li>\\n<li>홈 기록 카드와 마이페이지 배지 카드에 &quot;다음 배지 · 보름의 마음까지 8일&quot; 한 줄과 작은 진행 막대. 축하 카드 끝에 &quot;오늘 쓴 감사 다시 보기&quot; → <a href=\\"/grato-docs/features/stats-badges#next-badge\\">다음 배지</a></li>\\n<li>규칙(<code>badgesSeenAt</code>)·함수(<code>userBadges.progress</code>) 먼저, 그다음 Hosting. 앱은 iOS 1.0.1 (5)부터 → <a href=\\"/grato-docs/operations/deploy#release-badge-celebration\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-21","html":"<h3 id=\\"release-streak-recovery\\" tabindex=\\"-1\\">쉼표의 날과 기록한 날 먼저 <a class=\\"header-anchor\\" href=\\"#release-streak-recovery\\" aria-label=\\"Permalink to &quot;쉼표의 날과 기록한 날 먼저 {#release-streak-recovery}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li><strong>쉼표의 날</strong>: 연속일이 끊긴 다음 날 하루 안에 쓰면 비운 하루를 쉼표의 날로 바꿔 연속일이 이어짐(연속 3일 이상, 한 달에 한 번, 서버가 판단). 홈에 &quot;어제는 바쁜 하루였나 봐요. 오늘 쓰면 n일 연속으로 이어져요&quot; → <a href=\\"/grato-docs/features/stats-badges#rest-day\\">쉼표의 날</a></li>\\n<li><strong>기록한 날 먼저</strong>: 홈 카드 제목이 &quot;기록한 날 n일&quot;(누적, 끊겨도 줄지 않음), 연속일은 3일째부터 작은 칩. 끊긴 연속일을 0으로 보여 주지 않고 &quot;바쁜 날도 있죠. 기록한 날은 그대로 남아 있어요&quot;. 마이페이지 숫자 칸에 <strong>기록한 날</strong> 추가, 캘린더 카드는 연속일이 끊기면 그 달 최장 연속</li>\\n<li><strong>연속일 숨기기</strong>(설정): 홈·마이페이지·위젯·공유 캘린더·이름 옆에서 연속일을 숨김 → <a href=\\"/grato-docs/features/stats-badges#hide-streak\\">연속일 숨기기</a></li>\\n<li>함수·규칙 배포 뒤 <code>backfillActiveDays</code> 필요(<code>userStats.activeDays</code>, <code>restDays</code>, <code>users.hideStreak</code> 추가) → <a href=\\"/grato-docs/operations/deploy#release-streak-recovery\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-22","html":"<h3 id=\\"daily-topic\\" tabindex=\\"-1\\">모두의 감사방 오늘의 주제 <a class=\\"header-anchor\\" href=\\"#daily-topic\\" aria-label=\\"Permalink to &quot;모두의 감사방 오늘의 주제 {#daily-topic}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>모두의 감사방 탭 맨 위에 <strong>오늘의 주제</strong>: 매일 07:00(한국 시간)에 운영자가 예약한 질문 하나와 &quot;오늘 n명이 답했어요&quot;(3명 미만이면 &quot;첫 답을 남겨 보세요&quot;), [답하기], &quot;오늘 주제 말고 자유롭게 써도 돼요&quot; → <a href=\\"/grato-docs/features/circles#daily-topic\\">오늘의 주제</a></li>\\n<li>답은 <strong>감사 글</strong>로 저장되어 기록한 날·배지에 그대로 쌓임. 기본은 나만 보기, 이 방을 미리 고르지 않음, 제목은 쓰지 않아도 됨. 고를 수 있는 Circle은 모두의 감사방뿐</li>\\n<li>주제 아래 답은 시간순(새 답이 위), 인기순 없음. 답하기 전에는 새 답 3개만 보이고, 나만 보기로 답해도 전부 열림. 다른 사람 답의 공감 숫자는 보이지 않음(내 답은 보임)</li>\\n<li>답한 글 위에 &quot;오늘의 주제: …&quot;(내 기록·글 화면·지난 답). 선정된 사용자 질문은 방에서 이름 없이 &quot;💡 Grato 사용자가 제안한 질문&quot;</li>\\n<li>관리자 › <strong>주제</strong> 탭: 날짜별 예약(92일 뒤까지), 출처(운영자·선정 질문·시즌), 결. 서버가 문구(5~80자, 링크·연락처·욕설, &quot;AI&quot;·&quot;인공지능&quot;)와 8주 안 같은 문구를 막음 → <a href=\\"/grato-docs/decisions#adr-31\\">ADR-31</a></li>\\n<li>함수(<code>manageDailyTopic</code>) + Firestore 규칙·인덱스 → Hosting 순서. 앱은 iOS 1.0.1 (5)부터. 모두의 감사방이 꺼져 있는 동안 사용자 화면 변화 없음 → <a href=\\"/grato-docs/operations/deploy#release-daily-topic\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-23","html":"<h3 id=\\"comment-reactions\\" tabindex=\\"-1\\">댓글에도 공감 <a class=\\"header-anchor\\" href=\\"#comment-reactions\\" aria-label=\\"Permalink to &quot;댓글에도 공감 {#comment-reactions}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>댓글 아래 작은 버튼으로 공감(❤️ 🙏 ✨ 🔥)을 남김. 숫자는 작게, 댓글은 그대로 오래된 순. 배지로 받는 보상 공감은 글에만 → <a href=\\"/grato-docs/features/gratitudes#comment-reactions\\">댓글 공감</a>, <a href=\\"/grato-docs/decisions#adr-32\\">ADR-32</a></li>\\n<li>부모 글을 읽을 수 있는 사람만, 자기 공감만 켜고 끔. 숨긴 댓글에는 못 누름. 차단한 사람의 공감은 숫자에서 뺌. 모두의 감사방에서도 같음</li>\\n<li>댓글 공감 알림은 보내지 않음. 계정을 삭제하면 다른 사람 댓글에 남긴 공감도 지움</li>\\n<li>배포: firestore(규칙 + 인덱스 <code>comments.reactions</code>) → 인덱스 &quot;사용 설정됨&quot; 확인 → 함수(<code>deleteAccount</code>) → Hosting, 앱은 iOS 1.0.1 (5)부터 → <a href=\\"/grato-docs/operations/deploy#comment-reactions\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-26","html":"<h3 id=\\"ad-check\\" tabindex=\\"-1\\">모두의 감사방 광고 검사 <a class=\\"header-anchor\\" href=\\"#ad-check\\" aria-label=\\"Permalink to &quot;모두의 감사방 광고 검사 {#ad-check}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>운영자 신고 화면에 <strong>광고 의심</strong> 탭(모두의 감사방 자동 검사가 올린 열린 신고 모아 보기). 카드에 &quot;광고 의심&quot;과 걸린 징후(&quot;링크 · 한글로 쓴 번호&quot; 등)를 보여 줌 → <a href=\\"/grato-docs/features/safety#ad-check\\">광고 검사</a></li>\\n<li>내용 필터에 돌려 쓴 연락처(한글로 쓴 번호, 메신저 ID 안내, 돌려 쓴 링크)를 찾는 <code>findContactSignals</code>. 질문 제안 필터는 그대로 → <a href=\\"/grato-docs/decisions#adr-30\\">ADR-30</a></li>\\n<li><strong>쓸 때 검사</strong>: 모두의 감사방 글·댓글에 링크·이메일·전화번호나 돌려 쓴 연락처가 있으면 서버가 운영자 대기열에 올림(사유 스팸·광고, 숨기지 않음, 작성자에게 알리지 않음, 원문 복사 없음). 대상의 첫 신고만 운영자 푸시. 일반 Circle·나만 보기는 그대로 → <a href=\\"/grato-docs/features/safety#ad-check-on-write\\">쓸 때 검사</a></li>\\n<li><strong>6시간 검사</strong>: 새 예약 함수 <code>scanOpenCircleAds</code>(KST 0·6·12·18시)가 지난 7시간의 모두의 감사방 글·댓글에서 빠진 글, 같은 링크·번호 반복, 갓 들어온 계정의 연락처, 몰아쓰기·댓글 도배를 찾아 대기열에 올리고 운영자에게 &quot;광고 의심 n건&quot; 한 번 알림 → <a href=\\"/grato-docs/features/safety#ad-check-scan\\">6시간 검사</a></li>\\n<li>사용자 화면은 바뀌지 않음. 규칙 변경 없음. 새 인덱스(<code>comments.createdAt</code> 컬렉션 그룹)와 새 함수 → functions + firestore + Hosting 배포 → <a href=\\"/grato-docs/operations/deploy#release-ad-check\\">배포 주의</a></li>\\n</ul>\\n"},{"id":"GRATO-35","html":"<h3 id=\\"season-themes\\" tabindex=\\"-1\\">겨울·신년 이미지 테마와 감사 글·배지·초대장 이미지 <a class=\\"header-anchor\\" href=\\"#season-themes\\" aria-label=\\"Permalink to &quot;겨울·신년 이미지 테마와 감사 글·배지·초대장 이미지 {#season-themes}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>배지에 <strong>이미지 테마</strong>(겨울·신년)를 달 수 있음(관리자 › 배지). 그 배지를 받은 사람만 캘린더·배지·감사 글·초대장 이미지를 그 테마로 그림. 받은 테마는 빼지 않고, 잠금·가격 표시 없음 → <a href=\\"/grato-docs/features/stats-badges#themes\\">이미지 테마</a>, <a href=\\"/grato-docs/decisions#adr-37\\">ADR-37</a></li>\\n<li>새 이미지: 감사 글(작성자가 글 상세에서), 받은 배지(배지 상세), Circle 초대장(Circle 설정 › 초대, 초대 코드는 이미지에 넣지 않고 함께 가는 메시지에만). 캘린더 저장도 미리보기 시트로 열림</li>\\n<li>캘린더 이미지(기본 테마)의 옅은 글자를 진하게: 월·요일·&quot;기록한 날&quot;·기록 안 한 날 숫자 회색 400·300 → 500, &quot;기록한 날&quot; 숫자 주황 500 → 700. 바탕 위 대비 AA(4.5:1)</li>\\n<li>1.0.1 (4) 이하 앱은 테마를 몰라 늘 기본 모습(캘린더만). 고르기는 웹과 iOS 1.0.1 (5) 앱부터</li>\\n<li>배포: 함수(<code>evaluateBadges</code>)·규칙(<code>badges.theme</code>) 먼저 → 웹 → 앱 iOS 1.0.1 (5). 배지에 테마를 다는 것은 그 뒤 → <a href=\\"/grato-docs/features/stats-badges#themes\\">이미지 테마</a></li>\\n</ul>\\n"},{"id":"GRATO-37","html":"<h3 id=\\"release-ios-1-0-1-5\\" tabindex=\\"-1\\">iOS 1.0.1 (5) 빌드 <a class=\\"header-anchor\\" href=\\"#release-ios-1-0-1-5\\" aria-label=\\"Permalink to &quot;iOS 1.0.1 (5) 빌드 {#release-ios-1-0-1-5}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>iOS 빌드 번호를 5로(앱·위젯 확장, 버전은 1.0.1 그대로). 1.0.1 (4) 대신 이 빌드를 심사에 냄</li>\\n<li>앱에 새로 들어가는 것: 배지 축하 카드와 다음 배지, 쉼표의 날·기록한 날, 오늘의 주제(모두의 감사방은 꺼 둔 채), 댓글 공감, 시즌 배지 표시와 시즌 질문(날짜로 켜짐), 가입 직후 쓰기로 한 때와 그때를 말하는 매일 알림, 첫 나눔 표시, 이미지 테마, 올해의 감사 돌아보기(12/1부터), 그리고 지금까지 웹에만 있던 변경(호칭·연속일, 저장, 공지 등)</li>\\n<li>Cloud Tasks 준비 → 규칙·인덱스 → 함수 → Hosting → <code>backfillActiveDays</code> → 앱 보관·업로드 → <a href=\\"/grato-docs/operations/deploy#release-ios-1-0-1-5\\">배포 순서</a></li>\\n</ul>\\n"},{"id":"GRATO-60","html":"<h3 id=\\"signup-sources\\" tabindex=\\"-1\\">가입 유입 경로 기록 (꺼 둠) <a class=\\"header-anchor\\" href=\\"#signup-sources\\" aria-label=\\"Permalink to &quot;가입 유입 경로 기록 (꺼 둠) {#signup-sources}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>웹에서 캠페인 링크(UTM)로 처음 들어온 기기에 그 표시를 30일 보관했다가, 그 기기에서 <strong>가입할 때 한 번</strong> <code>users.signupSource</code>로 남기고 지움. UTM 없이 초대 링크로 들어오면 <code>invite</code>. 가입하지 않은 방문자는 서버에 아무것도 남지 않고, 앱에서는 모으지 않음 → <a href=\\"/grato-docs/architecture/data-model#users\\">데이터 모델</a></li>\\n<li>규칙: 문서를 만들 때만, 정해진 키·형식만(<code>isValidSignupSource</code>). 그 뒤 추가·변경·삭제 거부 → <a href=\\"/grato-docs/architecture/security-rules\\">보안 규칙</a></li>\\n<li>관리자 지표에 <strong>유입 경로</strong> 표(최근 90일 가입: 가입, 7일 안 첫 글, 비율, 캠페인 펼치기). 기존 &quot;가입 경로 · 사용 기기&quot;는 &quot;가입·사용 기기&quot;로 이름을 바꿈 → <a href=\\"/grato-docs/operations/metrics#signup-sources\\">운영 지표</a></li>\\n<li><strong>꺼진 채 배포</strong>: 개인정보 처리방침 개정 시행일 전에는 기기에도 남기지 않음(<code>SIGNUP_SOURCE_FROM = null</code>). 시행일을 넣어 배포하면 그날 0시(KST)부터 켜짐 → <a href=\\"/grato-docs/operations/deploy#release-signup-sources\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-71","html":"<h3 id=\\"season-badges\\" tabindex=\\"-1\\">시즌 배지: 기간에 기록한 날, 받은 배지는 기간 뒤에도 <a class=\\"header-anchor\\" href=\\"#season-badges\\" aria-label=\\"Permalink to &quot;시즌 배지: 기간에 기록한 날, 받은 배지는 기간 뒤에도 {#season-badges}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 배지 조건 <strong>&quot;시즌 기간에 기록한 날&quot;</strong>(<code>season_days</code>): 배지 기간(KST) 안에 글을 쓴 날 수. 하루 쉬어도 떨어지지 않고, 기간 전 기록은 세지 않음. 관리자 › 배지에서 기간(KST 날짜)·시즌 키를 넣어 만들고, 문서 ID는 <code>season_days_{값}_{시즌 키}</code> → <a href=\\"/grato-docs/features/stats-badges#season-badges\\">시즌 배지</a></li>\\n<li>관리자 배지 화면에 기간 입력(시작일 00:00–마지막 날 23:59)이 생김. 다른 기간 한정 배지에도 씀</li>\\n<li>마이페이지 배지: <strong>받은 배지는 기간이 끝나도 보임</strong>(예전에는 기간이 지나면 받은 사람에게도 숨김). 받지 않은 배지만 기간 밖에서 숨김</li>\\n<li>배지 상세: 기간(&quot;기간 11월 15일–12월 31일&quot;), 시즌 배지는 &quot;시즌 기간에 기록한 날 7일&quot;과 &quot;이번 시즌에 n일 기록했어요&quot;(정보만)</li>\\n<li>개발 빌드에만 있는 <a href=\\"/grato-docs/mobile/#dev-clock\\">테스트 날짜</a>로 시즌 화면을 미리 봄. Hosting predeploy가 이 빌드를 막음</li>\\n<li>함수 + Hosting 배포, 앱은 iOS 1.0.1 (5)부터(1.0.1 (4) 이하는 조건 줄에 영문 키가 보이고, 기간이 끝나면 받은 시즌 배지가 목록에서 빠짐). 규칙·인덱스 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-72","html":"<h3 id=\\"season-questions\\" tabindex=\\"-1\\">연말연초 시즌 질문 <a class=\\"header-anchor\\" href=\\"#season-questions\\" aria-label=\\"Permalink to &quot;연말연초 시즌 질문 {#season-questions}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li><strong>오늘의 질문이 시즌판</strong>: 11/15–11/30 &quot;감사의 계절&quot;(8개를 두 번), 12/1–12/31 &quot;한 해 돌아보기&quot;(연말 21개 + 12/22부터 1–6번 다시 + 12/28–12/31 마무리 4개), 1/1–1/10 &quot;신년 감사&quot; 10개. 쓰기 화면 카드·홈 화면 위젯·카드뉴스가 같은 날 같은 질문(KST). 1/11부터 기본 순환 → <a href=\\"/grato-docs/features/guided-writing#season-questions\\">시즌 질문</a></li>\\n<li>감사의 계절·한 해 돌아보기 질문 뒤 이어지는 질문은 시즌 질문 3개 중 하나. &quot;다른 질문&quot;은 그대로 풀 전체. 기본은 나만 보기</li>\\n<li><strong>매일 알림 문구</strong>: 시즌 날에는 &quot;오늘의 감사의 계절 질문이 기다려요 🍂&quot; / &quot;오늘의 한 해 돌아보기 질문이 기다려요 ❄️&quot; / &quot;오늘의 신년 감사 질문이 기다려요 🌅&quot;(초안). 웹 푸시와 앱 로컬 알림이 같은 문구 데이터(<code>reminderCopy.json</code> 두 사본) → <a href=\\"/grato-docs/features/notifications#daily-reminder-copy\\">매일 알림 문구</a></li>\\n<li>운영: <code>seedSeasonQuestions</code>로 11/15(일) 07:00에 넣고 2/1에 숨김(<code>--dry-run</code>, 멱등, 운영자가 숨긴 질문은 그대로) → <a href=\\"/grato-docs/operations/deploy#season-questions\\">배포: 시즌 질문</a>. 카드뉴스는 시즌 날짜에 자동으로 시즌 질문</li>\\n<li>분석: <code>gratitude_started</code>(질문으로 쓰기)에 시즌 질문이면 <code>seasonKey</code></li>\\n<li>개발 빌드에만 있는 <a href=\\"/grato-docs/mobile/#dev-clock\\">테스트 날짜</a>로 11/15·12/1·12/28·1/1·2/1을 미리 봄</li>\\n<li>함수(<code>sendDailyReminder</code>) + Hosting 배포, 앱은 iOS 1.0.1 (5)부터(1.0.1 (4) 이하는 시드된 시즌 질문을 &quot;다른 질문&quot;·순환 풀에서 만남). 규칙·인덱스 변경 없음 → <a href=\\"/grato-docs/decisions#adr-35\\">ADR-35</a></li>\\n</ul>\\n"},{"id":"GRATO-73","html":"<h3 id=\\"year-review\\" tabindex=\\"-1\\">올해의 감사 돌아보기 카드 (마이페이지, 시즌 기간만) <a class=\\"header-anchor\\" href=\\"#year-review\\" aria-label=\\"Permalink to &quot;올해의 감사 돌아보기 카드 (마이페이지, 시즌 기간만) {#year-review}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>시즌 기간(기본 12/1–1/31 KST)에 마이페이지 맨 위에 &quot;{연도}년 돌아보기&quot; 카드: 올해 고마움을 적은 날, 달마다 점, 펼치면 처음 쓴 감사·다시 읽어 볼 감사 3개·돌아보는 질문으로 쓰기. 나만 보고, 비교·순위 없음. 계산은 기기 안에서 내 글로만 → <a href=\\"/grato-docs/features/stats-badges#year-review\\">올해의 감사 돌아보기</a></li>\\n<li>&quot;이미지로 간직하기&quot;: 4:5 이미지, 기본은 숫자 없음(&quot;기록한 날 넣기&quot;를 켜야 들어감), 감사 글 제목·내용은 넣지 않음. 받은 이미지 테마(겨울·신년 등)로 그릴 수 있음(다른 이미지와 같은 시트)</li>\\n<li>운영: <code>appConfig/yearReview</code>로 앱 업데이트 없이 끄거나 기간을 옮김(<code>setupYearReview</code> 스크립트). Firestore 규칙 배포 필요(앱·웹보다 먼저) → <a href=\\"/grato-docs/operations/deploy#year-review\\">켜고 끄기</a>, <a href=\\"/grato-docs/decisions#adr-38\\">ADR-38</a></li>\\n<li>개발 빌드에서만 🕒로 날짜를 옮겨 볼 수 있음. Hosting predeploy가 그런 빌드의 배포를 막음</li>\\n</ul>\\n"},{"id":"GRATO-76","html":"<h3 id=\\"first-share\\" tabindex=\\"-1\\">Circle 첫 나눔 알림 문구 <a class=\\"header-anchor\\" href=\\"#first-share\\" aria-label=\\"Permalink to &quot;Circle 첫 나눔 알림 문구 {#first-share}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>한 사람이 <strong>그 Circle에 처음</strong> 나눈 글이면 멤버가 받는 새 글 알림이 &quot;{이름}님이 Circle에 처음 감사를 나눴어요 🌱&quot;(이름이 없으면 &quot;새 멤버가 …&quot;)로 바뀜. 받는 사람·설정·횟수는 그대로(알림이 늘지 않음), 모두의 감사방·자동 숨김된 글은 대상 아님 → <a href=\\"/grato-docs/features/notifications#first-share\\">첫 나눔 알림</a></li>\\n<li>서버 전용 표시 문서 <code>circleFirstShares/{groupId}_{uid}</code>(규칙 match 없음). 예전부터 그 Circle에 쓴 사람은 <code>legacy</code> 표시만 남고 문구는 그대로. 계정 삭제·Circle 삭제 때 함께 지움 → <a href=\\"/grato-docs/architecture/data-model#circle-first-shares\\">데이터 모델</a></li>\\n<li>알림 data에 <code>variant: &quot;first&quot;</code>(<code>type: circle_post</code> 그대로, 클릭 경로 같음). <code>notification_clicked</code> 이벤트에 <code>variant</code>를 담음(웹 포그라운드·앱 — 앱은 iOS 1.0.1 (5)부터)</li>\\n<li>함수 배포만 필요(규칙·인덱스 변경 없음, 앱 업데이트 없이 동작). 웹 클릭 이벤트는 Hosting 배포 때</li>\\n</ul>\\n"},{"id":"GRATO-77","html":"<h3 id=\\"first-share-followup\\" tabindex=\\"-1\\">첫 나눔에 24시간 반응이 없으면 리더에게 한 번 <a class=\\"header-anchor\\" href=\\"#first-share-followup\\" aria-label=\\"Permalink to &quot;첫 나눔에 24시간 반응이 없으면 리더에게 한 번 {#first-share-followup}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Circle 첫 나눔에 24시간 동안 다른 사람의 공감·댓글이 없으면 그 Circle <strong>리더에게만 한 번</strong> &quot;{이름}님이 처음 나눈 감사가 있어요 / {글 제목} · 공감이나 댓글로 반겨 줄 수 있어요&quot;. 밤(KST 22:00–08:59)이면 다음 09:00, 리더당 하루 1회, 리더의 Circle 새 글 알림 설정을 따름. 쓰는 사람에게는 아무것도 가지 않음 → <a href=\\"/grato-docs/features/notifications#first-share-followup\\">리더 알림</a></li>\\n<li>새 작업 큐 함수 <code>firstShareFollowup</code>(Cloud Tasks, 글마다 작업 하나). 결과는 첫 나눔 표시 문서의 <code>followupAt</code>·<code>followupSent</code>·<code>followupSkipped</code> → <a href=\\"/grato-docs/decisions#adr-33\\">ADR-33</a></li>\\n<li>함수 배포만(앱 업데이트 없이 동작). <strong>처음 한 번 Cloud Tasks API·IAM 역할 설정 필요</strong>(CI 배포 계정에 <code>roles/cloudtasks.queueAdmin</code>) → <a href=\\"/grato-docs/operations/deploy#cloud-tasks\\">배포: Cloud Tasks</a>. 로컬 에뮬레이터에 <code>tasks</code> 추가</li>\\n</ul>\\n"},{"id":"GRATO-78","html":"<h3 id=\\"first-share-metrics\\" tabindex=\\"-1\\">관리자 지표 &quot;첫 나눔&quot; 칸 <a class=\\"header-anchor\\" href=\\"#first-share-metrics\\" aria-label=\\"Permalink to &quot;관리자 지표 &quot;첫 나눔&quot; 칸 {#first-share-metrics}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 분석 화면의 지표에 <strong>첫 나눔 · 최근 4주</strong>: 7일 안에 다시 나눔(주 지표), 24시간 안 첫 반응, 첫 반응까지 시간 중앙값, 리더 알림 보냄·건너뜀(이유별)·보낸 뒤 24시간 반응, Circle 새 글 알림 끈 사람(감시), 출시 전 4주 다시 나눔(비교 기준) → <a href=\\"/grato-docs/operations/metrics#first-shares\\">지표: 첫 나눔</a></li>\\n<li>공감·댓글 트리거가 만든 지 72시간 안의 첫 나눔에 첫 반응 시각(<code>firstResponseAt</code>·<code>firstResponseType</code>)을 한 번 기록</li>\\n<li>함수 + Hosting 배포(규칙·인덱스 변경 없음). 사용자에게 보이는 숫자는 없음</li>\\n</ul>\\n"},{"id":"GRATO-79","html":"<h3 id=\\"first-share-ui\\" tabindex=\\"-1\\">첫 나눔 화면 표시 <a class=\\"header-anchor\\" href=\\"#first-share-ui\\" aria-label=\\"Permalink to &quot;첫 나눔 화면 표시 {#first-share-ui}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Circle에 처음 나눈 글: 저장 직후 그 Circle 피드 위에 <strong>&quot;Circle 멤버에게 알렸어요&quot;</strong>(5초, 이 기기의 피드로 추측, 숫자 없음), Circle 피드 카드에 7일 동안 <strong>&quot;처음 나눈 감사&quot;</strong> → <a href=\\"/grato-docs/features/circles#first-share\\">첫 나눔</a></li>\\n<li>서버가 첫 나눔 글에 <code>firstShare: true</code>를 씀(클라이언트 쓰기 거부, 규칙 테스트 추가). 모두의 감사방·내 기록·저장한 감사에는 표시 없음</li>\\n<li>함수 + Hosting 배포(규칙 파일 변경 없음 — 기존 생성·수정 규칙이 이미 막음). 앱은 iOS 1.0.1 (5)부터</li>\\n</ul>\\n"},{"id":"GRATO-80","html":"<h3 id=\\"pr-checks\\" tabindex=\\"-1\\">PR마다 테스트 자동 실행, 변경 이력은 PR별 파일로 <a class=\\"header-anchor\\" href=\\"#pr-checks\\" aria-label=\\"Permalink to &quot;PR마다 테스트 자동 실행, 변경 이력은 PR별 파일로 {#pr-checks}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>PR과 <code>main</code> push마다 GitHub Actions <strong>Test</strong> 워크플로가 클라이언트·함수 단위·보안 규칙·함수 엔드투엔드·웹 빌드·문서 빌드를 나란히 돌림. 바뀐 경로만 돌고, 마지막 <strong>Test summary</strong>가 하나로 묶음(필수 검사로 지정 가능). 비밀값·Google 자격 증명 없음 → <a href=\\"/grato-docs/operations/testing#ci\\">CI 테스트</a></li>\\n<li>변경 이력은 이제 PR마다 <code>docs/changelog/unreleased/&lt;티켓&gt;.md</code>에 쓰고, 배포할 때 <code>npm run changelog</code>로 합침. 열린 PR끼리 <code>changelog.md</code> 맨 위에서 충돌하지 않음 → <a href=\\"/grato-docs/decisions#adr-36\\">ADR-36</a>, <a href=\\"/grato-docs/contributing-docs#changelog\\">변경 이력 쓰기</a></li>\\n<li>앱·서버 동작 변경 없음(배포할 것 없음)</li>\\n</ul>\\n"},{"id":"GRATO-81","html":"<h3 id=\\"writing-plan\\" tabindex=\\"-1\\">가입 직후 &quot;언제 감사를 떠올릴까요?&quot; <a class=\\"header-anchor\\" href=\\"#writing-plan\\" aria-label=\\"Permalink to &quot;가입 직후 &quot;언제 감사를 떠올릴까요?&quot; {#writing-plan}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 계정은 동의를 마친 뒤 한 화면에서 감사를 떠올릴 때를 고름: 아침 차 한 잔 할 때 · 출근·등교길 · 점심 먹고 나서 · 퇴근·하교길 · 잠들기 전 · 내가 정한 때(시각은 15분 단위로 바꿈). 고르면 &quot;잠들기 전이 되면, 고마웠던 일을 한 줄 적어요.&quot; 같은 계획 문장 → <a href=\\"/grato-docs/features/account#writing-plan\\">가입 직후</a></li>\\n<li>고른 때가 매일 감사 알림 시각이 됨. <strong>이 시간에 알려 주세요</strong>를 누를 때만 알림 권한을 묻고, <strong>알림 없이 정해 둘게요</strong>·<strong>건너뛰기</strong>도 있음. 권한을 거부하거나 알림이 안 되는 브라우저여도 계획은 저장</li>\\n<li>초대 링크로 가입한 사람과 이미 가입한 사람(계획 없음)은 홈에 카드가 한 번 보임. 마이페이지 &gt; 설정에 <strong>쓰기로 한 때</strong> 줄(바꾸기)</li>\\n<li><code>users.writingPlan</code> 추가, 규칙이 모양을 검사 → <a href=\\"/grato-docs/architecture/security-rules#writing-plan\\">보안 규칙</a>. 배포: 규칙 → Hosting → 앱(iOS 1.0.1 (5)). 함수 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-82","html":"<h3 id=\\"daily-reminder-cue\\" tabindex=\\"-1\\">매일 알림이 고른 때를 말함 <a class=\\"header-anchor\\" href=\\"#daily-reminder-cue\\" aria-label=\\"Permalink to &quot;매일 알림이 고른 때를 말함 {#daily-reminder-cue}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>쓰기로 한 때를 골랐으면 매일 알림 제목이 그 때를 말함: &quot;잠들기 전, 오늘의 감사 한 줄 🌙&quot;, &quot;점심 뒤 잠깐, 오늘의 감사 한 줄 🍚&quot; 등. &quot;내가 정한 때&quot;·계획 없음·알림 시각을 따로 바꾼 경우는 예전 문구 → <a href=\\"/grato-docs/features/notifications#daily-reminder-copy\\">매일 알림 문구</a></li>\\n<li>웹 푸시와 앱 휴대폰 알림이 같은 문구 파일(<code>reminderCopy.json</code>)을 씀. 시즌 문구가 들어오면 시즌 문구 앞에 때 단서를 붙임</li>\\n<li>알림 횟수·조건은 그대로. 알림을 누르면 <code>notification_clicked</code>에 <code>cue</code></li>\\n<li>배포: 함수(<code>sendDailyReminder</code>) → 앱(iOS 1.0.1 (5), 휴대폰 알림 문구). 규칙·인덱스 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-83","html":"<h3 id=\\"metrics-writing-plan\\" tabindex=\\"-1\\">관리자 지표: 가입 7일 안 3일 기록 <a class=\\"header-anchor\\" href=\\"#metrics-writing-plan\\" aria-label=\\"Permalink to &quot;관리자 지표: 가입 7일 안 3일 기록 {#metrics-writing-plan}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 지표에 <strong>가입 7일 안 3일 기록</strong> 비율: 최근 8주 가입 주별로 전체와 그룹(계획 · 알림 켬 / 알림 없이, 건너뜀, 보고 나감, 안 봄), <strong>기능 전 4주 ↔ 기능 뒤</strong> 비교, 계획 세운 비율 → <a href=\\"/grato-docs/operations/metrics#writing-plan\\">가입 7일 안 3일</a></li>\\n<li>쓰기로 한 때별 계획 수·알림 켬·최근 28일 매일 알림 누름(사람·일당 근사값)</li>\\n<li>그룹은 스스로 고른 사람이라 치우친다는 안내를 화면에 한 줄. 운영자 제외, 사람별 값 없음</li>\\n<li>함수(<code>adminMetrics</code>) + Hosting 배포. 새 인덱스 없음(오늘 현황의 <code>analyticsEvents (event, createdAt)</code> 사용), 규칙 변경 없음</li>\\n</ul>\\n"},{"id":"GRATO-94-android","html":"<h3 id=\\"android-release-workflow\\" tabindex=\\"-1\\">Android 빌드를 GitHub Actions로 Play 내부 테스트까지 <a class=\\"header-anchor\\" href=\\"#android-release-workflow\\" aria-label=\\"Permalink to &quot;Android 빌드를 GitHub Actions로 Play 내부 테스트까지 {#android-release-workflow}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Actions의 <strong>Android release</strong>를 손으로 시작하면 오너 승인 뒤 웹 빌드·<code>cap sync android</code>·AAB 빌드(업로드 키 서명)를 하고, AAB를 아티팩트로 남긴 뒤 Play 내부 테스트(또는 비공개 테스트) 트랙에 올립니다. 프로덕션 트랙·심사·스토어 문구는 건드리지 않습니다 → <a href=\\"/grato-docs/operations/ci-mobile#android\\">앱 빌드 CI</a></li>\\n<li><code>versionCode</code>는 입력값 또는 실행 번호 + 오프셋(기본 5)이고, 커밋된 값보다 커야 합니다 → <a href=\\"/grato-docs/operations/ci-mobile#versions\\">버전 번호</a></li>\\n<li><code>android/app/build.gradle</code>은 <code>keystore.properties</code>가 없을 때 환경 변수로도 업로드 키를 읽습니다(맥에서의 빌드는 그대로).</li>\\n</ul>\\n"},{"id":"GRATO-94-ios","html":"<h3 id=\\"ios-xcode-cloud\\" tabindex=\\"-1\\">iOS 빌드를 Xcode Cloud로, 버전 번호 한 번에 바꾸기 <a class=\\"header-anchor\\" href=\\"#ios-xcode-cloud\\" aria-label=\\"Permalink to &quot;iOS 빌드를 Xcode Cloud로, 버전 번호 한 번에 바꾸기 {#ios-xcode-cloud}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>Xcode Cloud가 저장소의 <code>ios/App/ci_scripts/</code>로 웹 빌드·<code>cap sync ios</code>를 하고, 앱·위젯 빌드 번호를 Xcode Cloud 번호로 맞춰 TestFlight 내부 테스트까지 올립니다. 시작은 손으로 또는 <code>release/ios-*</code> 태그, 심사 제출은 오너가 손으로 → <a href=\\"/grato-docs/operations/ci-mobile#ios\\">앱 빌드 CI</a></li>\\n<li><code>npm run version:bump -- --version 1.0.2 --build 6</code>: iOS 앱·위젯과 Android의 버전·빌드 번호를 한 번에 바꿉니다(빌드 번호는 올라가기만) → <a href=\\"/grato-docs/operations/ci-mobile#versions\\">버전 번호</a></li>\\n<li>Xcode Cloud가 쓰도록 scheme <code>App</code>을 공유 scheme으로 커밋했습니다.</li>\\n</ul>\\n"},{"id":"GRATO-94-preview","html":"<h3 id=\\"pr-web-preview\\" tabindex=\\"-1\\">PR 웹 미리보기 <a class=\\"header-anchor\\" href=\\"#pr-web-preview\\" aria-label=\\"Permalink to &quot;PR 웹 미리보기 {#pr-web-preview}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>같은 저장소 PR에서 테스트가 통과하면 그 PR의 웹 화면을 Firebase Hosting 미리보기 주소(<code>pr-&lt;번호&gt;</code>, 7일 뒤 사라짐)에 올리고 PR에 링크 댓글을 답니다. 운영 사이트(grato.today)에는 올리지 않습니다. 미리보기는 운영 데이터에 붙으므로 테스트 계정으로만 확인합니다 → <a href=\\"/grato-docs/operations/deploy#ci-preview\\">PR 웹 미리보기</a></li>\\n<li>오너 설정(Environment <code>preview</code>, 미리보기 전용 WIF 풀·서비스 계정, 저장소 수준 웹 설정 값)을 마친 뒤부터 동작합니다 → <a href=\\"/grato-docs/decisions#adr-39\\">ADR-39</a></li>\\n</ul>\\n"},{"id":"GRATO-103","html":"<h3 id=\\"environments-stg\\" tabindex=\\"-1\\">테스트용 stg 환경과 PR 미리보기 분리 <a class=\\"header-anchor\\" href=\\"#environments-stg\\" aria-label=\\"Permalink to &quot;테스트용 stg 환경과 PR 미리보기 분리 {#environments-stg}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>개발자 환경을 dev(로컬 에뮬레이터) · stg(별도 Firebase 프로젝트 <code>grato-stg</code>) · prod로 나눔. 사용자에게 보이는 변화는 없음</li>\\n<li>PR 웹 미리보기가 운영 데이터 대신 stg에 붙음. 배포 워크플로는 <code>target-env</code>(기본 stg)로 대상을 고르고 운영은 <code>main</code>에서만</li>\\n<li>시드·백필·설정 스크립트는 대상 프로젝트를 검사하고, 운영에는 <code>GRATO_CONFIRM_PROJECT=grato-44d47</code>을 함께 줘야 돎</li>\\n<li>오너 설정(요금제·API·로그인·WIF·GitHub 변수)이 끝나기 전에는 Preview 워크플로가 실패할 수 있음 → <a href=\\"/grato-docs/operations/deploy#environments\\">환경</a>, <a href=\\"/grato-docs/decisions#adr-40\\">ADR-40</a></li>\\n</ul>\\n"}]'),d={key:0},u=["innerHTML"],f=JSON.parse('{"title":"변경 이력","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792220032000}'),h={name:"changelog.md"},m=Object.assign(h,{setup(q){return(g,e)=>(o(),a("div",null,[e[0]||(e[0]=r('<h1 id="변경-이력" tabindex="-1">변경 이력 <a class="header-anchor" href="#변경-이력" aria-label="Permalink to &quot;변경 이력&quot;">​</a></h1><p>사용자에게 보이는 변경과 운영에 영향을 주는 변경을 최신순으로 기록합니다.</p><h2 id="unreleased" tabindex="-1">아직 합치지 않은 변경 <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;아직 합치지 않은 변경 {#unreleased}&quot;">​</a></h2><p>PR마다 <code>docs/changelog/unreleased/</code>에 따로 쓴 항목입니다. 배포할 때 날짜를 붙여 아래 목록으로 옮깁니다 → <a href="/grato-docs/contributing-docs#changelog">변경 이력 쓰기</a></p>',4)),t(l).length?s("",!0):(o(),a("p",d,"없음")),(o(!0),a(c,null,n(t(l),i=>(o(),a("div",{key:i.id,class:"unreleased-entry",innerHTML:i.html},null,8,u))),128)),e[1]||(e[1]=r('<h2 id="primary-color" tabindex="-1">2026-10-17 — 주 버튼 색을 더 진하게 (배포 전) <a class="header-anchor" href="#primary-color" aria-label="Permalink to &quot;2026-10-17 — 주 버튼 색을 더 진하게 (배포 전) {#primary-color}&quot;">​</a></h2><ul><li>흰 글자를 얹는 버튼·탭·스위치·쓰기 버튼을 더 진한 주황 <code>#B45309</code>로 바꿈. 흰 글자 대비가 2.2:1에서 5.0:1이 되어 WCAG AA를 통과 → <a href="/grato-docs/architecture/client#visual-style">화면 스타일</a></li><li>앱 설치 배너도 같은 색(그라데이션 대신 한 색), 공유 캘린더 페이지의 기록한 날은 앱 캘린더와 같은 연한 주황 + 짙은 글자</li><li>로고·앱 아이콘·장식의 밝은 주황은 그대로. 규칙·함수 변경 없음: 웹은 Hosting 배포, 앱은 다음 빌드부터</li></ul><h2 id="analytics-ttl" tabindex="-1">기능 이용 기록 180일 보관 <a class="header-anchor" href="#analytics-ttl" aria-label="Permalink to &quot;기능 이용 기록 180일 보관 {#analytics-ttl}&quot;">​</a></h2><ul><li>기능 이용 기록(<code>analyticsEvents</code>)에 만료 시각 <code>expireAt</code>(기록 + 180일)을 넣고 Firestore TTL로 지움. 쿼리에 쓰지 않는 <code>props</code>·<code>platform</code>·<code>expireAt</code>은 단일 필드 인덱스에서 뺌 → <a href="/grato-docs/decisions#adr-26">ADR-26</a></li><li>예전 기록은 <code>backfillAnalyticsExpireAt</code>으로 <code>createdAt + 180일</code>을 채움(180일이 지난 기록은 곧 지워짐)</li><li>함수 + firestore(규칙·TTL·인덱스 제외) + Hosting 배포, 그다음 스크립트 → <a href="/grato-docs/operations/deploy#analytics-ttl">보관 기간 켜기</a></li></ul><h2 id="ios-web-push-guide" tabindex="-1">2026-10-17 — iPhone·iPad 웹 알림: App Store 앱 안내 (배포 전) <a class="header-anchor" href="#ios-web-push-guide" aria-label="Permalink to &quot;2026-10-17 — iPhone·iPad 웹 알림: App Store 앱 안내 (배포 전) {#ios-web-push-guide}&quot;">​</a></h2><ul><li>iPhone·iPad 웹(Safari·Chrome·카카오톡 안 브라우저)에서 알림을 쓸 수 없으면 설정 맨 위 카드가 &quot;다른 브라우저를 사용해보세요&quot; 대신 <strong>&quot;알림은 Grato 앱에서 받을 수 있어요&quot;</strong> 와 <strong>App Store에서 받기</strong> 버튼을 보임. Android·PC의 미지원 브라우저는 그대로</li><li>웹에서 알림을 쓸 수 없는 브라우저면 감사 알림 시간 아래 설명이 &quot;이 브라우저에서는 알림이 오지 않아요. 위 안내를 확인해 주세요&quot;</li><li>iPhone·iPad 웹 홈에 닫을 수 있는 App Store 안내 카드(권한을 묻지 않음, 한 번 닫으면 다시 안 보임)</li><li>앱 화면은 바뀌지 않음. 데이터·규칙·함수 변경 없음(Hosting 배포만) → <a href="/grato-docs/features/notifications#ios-web">iPhone·iPad 웹</a></li></ul><h2 id="faq-support-copy" tabindex="-1">2026-10-17 — 자주 묻는 질문·고객지원 안내를 지금 화면에 맞춤 (배포 전) <a class="header-anchor" href="#faq-support-copy" aria-label="Permalink to &quot;2026-10-17 — 자주 묻는 질문·고객지원 안내를 지금 화면에 맞춤 (배포 전) {#faq-support-copy}&quot;">​</a></h2><ul><li>자주 묻는 질문(<code>/faq</code>): 알림 설정 안내를 <strong>마이페이지 &gt; 설정</strong>의 매일 감사 알림·감사 알림 시간(15분 단위, 처음 오후 9시)으로, 차단 안내를 글·댓글의 ⋯ 메뉴 › 차단하기로 고침</li><li>새 질문 3개: Apple로 가입했더니 이름이 &quot;익명&quot;으로 보여요 / 알림이 오지 않아요 / 홈 화면 위젯이 있나요?</li><li>고객지원(<code>/support</code>) 신고 안내를 &quot;사람&quot;(⋯ › 차단하기, Circle 설정의 이 멤버 신고하기)과 &quot;Circle&quot;(Circle 설정의 Circle 신고하기)로 나눔</li><li>차단 확인 창: &quot;마이페이지 &gt; 설정 &gt; 차단한 사용자에서 언제든 해제할 수 있어요&quot;(앱은 다음 빌드부터)</li><li>약관·처리방침 본문과 <code>TERMS_VERSION</code>은 그대로(메뉴 이름 &quot;마이페이지 &gt; 설정&quot;은 이미 같음). 자주 묻는 질문·고객지원도 다른 플랫폼 이름을 쓰지 않는지 테스트로 확인</li></ul><h2 id="admin-today-kst" tabindex="-1">관리자 오늘 현황을 KST 기준으로 <a class="header-anchor" href="#admin-today-kst" aria-label="Permalink to &quot;관리자 오늘 현황을 KST 기준으로 {#admin-today-kst}&quot;">​</a></h2><ul><li>관리자 분석 화면의 <strong>오늘 현황</strong>이 관리자 기기의 자정이 아니라 <strong>KST 자정</strong>부터 셉니다. 제목 옆에 기준 날짜(&quot;10월 17일 · 한국 시간&quot;) 표시 → <a href="/grato-docs/operations/metrics#today">오늘 현황</a></li><li>오늘 이벤트 문서를 모두 내려받지 않고 이벤트별 count 쿼리로 셈(읽기 비용 감소). 새 복합 인덱스 <code>analyticsEvents (event, createdAt)</code> — 인덱스가 준비되기 전에는 예전처럼 문서를 읽어 셈</li><li>Firestore 인덱스 + Hosting 배포 필요(규칙·함수 변경 없음)</li></ul><h2 id="reactions-from-others" tabindex="-1">받은 공감 배지 셈 고침, 호칭 가이드 <a class="header-anchor" href="#reactions-from-others" aria-label="Permalink to &quot;받은 공감 배지 셈 고침, 호칭 가이드 {#reactions-from-others}&quot;">​</a></h2><ul><li><strong>받은 공감 배지</strong>(<code>reactions_received</code>)는 이제 글마다 나 아닌 사람 수를 셉니다. 내가 내 글에 누른 공감, 한 사람이 같은 글에 누른 여러 이모지는 더 세지 않음 → <a href="/grato-docs/features/stats-badges#conditions">조건 종류</a></li><li>배지에 호칭을 달 때의 기준과 배지별 호칭 → <a href="/grato-docs/features/stats-badges#title-guide">호칭 가이드</a></li><li>관리자 배지 화면: 호칭 예시를 가이드에 맞추고, 조건 이름 &quot;받은 리액션&quot;을 &quot;받은 공감&quot;으로</li><li>함수 배포 필요. <strong>받은 공감 배지는 함수 배포 뒤에 만들 것</strong>(먼저 만들면 예전 셈으로 지급되고 회수하지 않음)</li></ul><h2 id="release-name-tags" tabindex="-1">2026-10-17 — 이름 옆 꾸밈: 호칭과 &quot;n일째 감사 중&quot; (2026-10-17 배포) <a class="header-anchor" href="#release-name-tags" aria-label="Permalink to &quot;2026-10-17 — 이름 옆 꾸밈: 호칭과 &quot;n일째 감사 중&quot; (2026-10-17 배포) {#release-name-tags}&quot;">​</a></h2><ul><li><strong>호칭</strong>: 관리자가 배지에 호칭을 달면 그 배지를 얻은 사람이 받고, 마이페이지 <strong>&quot;이름 꾸미기&quot;</strong> 에서 골라 이름 옆에 붙임(글·댓글). 시즌 배지에 달면 시즌 호칭. 고르면 지난 글·댓글도 바뀜 → <a href="/grato-docs/features/stats-badges#titles">호칭</a></li><li><strong>연속 감사 보여주기</strong>: 켜면 새 글의 이름 옆에 &quot;🔥 12일째 감사 중&quot;(서버가 그날 값을 찍음) → <a href="/grato-docs/features/stats-badges#show-streak">연속 감사 보여주기</a></li><li>모두의 감사방에서도 별명 옆에 보임. 배지 상세에 &quot;보상 호칭&quot; 표시</li><li>규칙·함수 배포 필요(<code>publicProfiles.title</code>, <code>authorTitle</code>, <code>authorStreak</code>, <code>users.showStreak</code>)</li></ul><h2 id="release-reward-reactions" tabindex="-1">2026-10-17 — 배지 보상 공감 이모지 (꺼 둠, 2026-10-17 배포) <a class="header-anchor" href="#release-reward-reactions" aria-label="Permalink to &quot;2026-10-17 — 배지 보상 공감 이모지 (꺼 둠, 2026-10-17 배포) {#release-reward-reactions}&quot;">​</a></h2><ul><li>배지를 얻은 사람만 쓰는 공감 이모지 구조: 🌸(7일 연속) 🍀(감사 50개) 🌈(30일 연속). <strong>처음엔 모두 꺼짐</strong>, 운영자가 <code>setupReactionRewards --enable</code>로 켜면 이미 배지를 가진 사람에게 바로 지급 → <a href="/grato-docs/features/stats-badges#reward-reactions">보상 공감</a></li><li>켜진 보상은 공감 고르기 창에 나오고, 아직 못 받은 것은 자물쇠와 &quot;&#39;…&#39; 배지를 받으면 쓸 수 있어요&quot;</li><li>규칙: 보상 이모지는 받은 사람만 더할 수 있음(규칙 배포 필요). <code>userBadges.reactions</code>, <code>appConfig/reactionRewards</code> 추가</li><li>댓글 입력 안내를 어디서나 &quot;댓글을 남겨보세요&quot;로(모두의 감사방 포함)</li></ul><h2 id="release-write-banner" tabindex="-1">2026-10-17 — 질문으로 쓰기 배너, 카드 여백 (2026-10-17 배포) <a class="header-anchor" href="#release-write-banner" aria-label="Permalink to &quot;2026-10-17 — 질문으로 쓰기 배너, 카드 여백 (2026-10-17 배포) {#release-write-banner}&quot;">​</a></h2><ul><li>쓰기 화면의 질문 상자를 잔잔한 배너로: 새싹 로고와 &quot;질문으로 쓰기&quot;, 질문 문장, 흰 알약 버튼 [이 질문으로 감사 적기 ›], &quot;다른 질문&quot;은 오른쪽 위 아이콘, 오른쪽 아래 흐린 새싹</li><li>피드 카드: 본문과 공감하기 사이 여백을 넓힘</li></ul><h2 id="release-notices" tabindex="-1">2026-10-17 — 공지 (2026-10-17 배포) <a class="header-anchor" href="#release-notices" aria-label="Permalink to &quot;2026-10-17 — 공지 (2026-10-17 배포) {#release-notices}&quot;">​</a></h2><ul><li>운영자가 관리자 › 공지 탭에서 공지를 올리고 고치고 지움(<code>manageNotice</code>, 감사 기록). 누구나 설정 › <strong>공지사항</strong>(<code>/notices</code>)에서 봄</li><li>&quot;홈 배너&quot;로 올린 최근 공지는 홈 맨 위에 보이고 X로 닫음(기기마다) → <a href="/grato-docs/features/notices">공지</a></li><li>새 컬렉션 <code>notices</code>(읽기 누구나, 쓰기는 서버만), 새 함수 <code>manageNotice</code> — 함수·규칙 배포 필요</li></ul><h2 id="release-inline-comments" tabindex="-1">2026-10-17 — 댓글은 카드 안에서 펼치기 (2026-10-17 배포) <a class="header-anchor" href="#release-inline-comments" aria-label="Permalink to &quot;2026-10-17 — 댓글은 카드 안에서 펼치기 (2026-10-17 배포) {#release-inline-comments}&quot;">​</a></h2><ul><li>피드 카드의 [댓글]을 누르면 글 화면으로 넘어가지 않고 카드 안에 댓글이 펼쳐짐(다시 누르면 접힘). 그 자리에서 댓글을 쓰고 지우고 신고·차단 → <a href="/grato-docs/features/gratitudes">댓글</a></li></ul><h2 id="release-bookmarks" tabindex="-1">2026-10-17 — 감사 저장(책갈피) (2026-10-17 배포) <a class="header-anchor" href="#release-bookmarks" aria-label="Permalink to &quot;2026-10-17 — 감사 저장(책갈피) (2026-10-17 배포) {#release-bookmarks}&quot;">​</a></h2><ul><li>피드 카드와 글 상세의 <strong>[저장]</strong> 으로 글을 저장하고, 마이페이지 <strong>&quot;저장한 감사&quot;</strong> (<code>/saved</code>)에서 따로 봄. 내 글·Circle 글 모두, 목록은 나만 봄 → <a href="/grato-docs/features/gratitudes#bookmarks">저장</a></li><li>지워졌거나 나간 Circle의 글은 &quot;더 볼 수 없는 글이에요&quot;와 [목록에서 빼기]</li><li>저장한 감사 카드에 어느 Circle의 글인지(또는 나만 보기) 표시</li><li>새 하위 컬렉션 <code>users/{uid}/bookmarks</code>(본인만, 규칙 배포 필요). 처리방침의 수집 항목·계정 삭제 안내에 &quot;저장한 글 목록&quot; 추가</li></ul><h2 id="release-circle-order" tabindex="-1">2026-10-17 — Circle 순서 바꾸기 (2026-10-17 배포) <a class="header-anchor" href="#release-circle-order" aria-label="Permalink to &quot;2026-10-17 — Circle 순서 바꾸기 (2026-10-17 배포) {#release-circle-order}&quot;">​</a></h2><ul><li>Circle 탭 &quot;내 Circle&quot;의 <strong>[순서 바꾸기]</strong> 로 ↑·↓ 위치를 정하면 홈 탭(내 기록 다음)·Circle 목록·쓰기 화면의 Circle 선택이 그 순서로 보임. 계정에 저장(<code>users.circleOrder</code>), 다른 기기도 같음 → <a href="/grato-docs/features/circles#order">순서 바꾸기</a></li><li>규칙: <code>circleOrder</code>는 최대 20개 목록만 (규칙 배포 필요)</li></ul><h2 id="release-write-compact" tabindex="-1">2026-10-17 — 쓰기 화면 더 간단하게 (2026-10-17 배포) <a class="header-anchor" href="#release-write-compact" aria-label="Permalink to &quot;2026-10-17 — 쓰기 화면 더 간단하게 (2026-10-17 배포) {#release-write-compact}&quot;">​</a></h2><ul><li>입력란 위의 &quot;제목&quot;·&quot;내용&quot;·&quot;누가 볼 수 있나요?&quot; 라벨을 빼서 한 화면에 더 들어오게 함(안내 문구는 그대로)</li><li>&quot;무엇을 쓸지 막막하다면&quot;을 작은 점선 상자로(질문 문장 + &quot;이 질문으로 감사 적기 ›&quot;), 저장 버튼 바로 아래라 첫 화면에 보임</li><li>쓰기 화면 상단 Grato 로고를 홈과 같은 크기로</li></ul><h2 id="release-1-0-1" tabindex="-1">2026-10-17 — 서버·웹 배포, 앱 1.0.1 (4) <a class="header-anchor" href="#release-1-0-1" aria-label="Permalink to &quot;2026-10-17 — 서버·웹 배포, 앱 1.0.1 (4) {#release-1-0-1}&quot;">​</a></h2><ul><li>함수(새로 <code>joinOpenCircle</code>·<code>renameOpenCircleAlias</code>·<code>onPublicProfileUpdated</code>·<code>onOpenCircleAliasUpdated</code>, 나머지 23개 갱신)·Firestore 규칙·Hosting 배포. 아래 2026-10-12~16 항목이 이때 운영에 반영됨(모두의 감사방은 꺼진 채)</li><li>백필 3개 실행(같은 날): 최대 연속일 13개 계정, 댓글 작성자 글 25개, 예전 이름·사진으로 남은 글 42개·댓글 29개(4개 계정)를 지금 프로필로</li><li>앱 1.0.1 (4): iOS는 App Store Connect 업로드(TestFlight, 심사 제출 전), Android는 Play 내부 테스트 게시. 지난 앱 빌드 뒤의 화면 변경(하단 탭 이름, 마이페이지·설정, 쓰기 화면, 캘린더 로고, 문구)이 앱에 들어감</li><li>출시 전 QA에서 고친 것: 질문으로 쓰기에서 휴대폰 뒤로 가기(Android 뒤로, iOS 스와이프)가 쓰기 화면이 아니라 홈으로 가던 것. 질문으로 쓰기가 자기 주소(<code>/write?mode=guided…</code>)를 가져 뒤로 가면 쓰던 내용이 있는 쓰기 화면으로 돌아옴</li></ul><h2 id="release-author-sync" tabindex="-1">2026-10-16 — 이름·사진·별명을 바꾸면 지난 글에도 (2026-10-17 배포) <a class="header-anchor" href="#release-author-sync" aria-label="Permalink to &quot;2026-10-16 — 이름·사진·별명을 바꾸면 지난 글에도 (2026-10-17 배포) {#release-author-sync}&quot;">​</a></h2><ul><li>프로필의 이름이나 사진을 바꾸면(사진 삭제 포함) 지금까지 쓴 글·댓글에도 새 이름·사진이 보임. 서버가 몇 초 안에 바꿈. 모두의 감사방 글은 그대로 별명 → <a href="/grato-docs/features/account#profile-change">이름·사진을 바꾸면</a></li><li>모두의 감사방 별명을 <strong>Circle 설정 › [바꾸기]</strong> 로 바꿀 수 있음(7일에 한 번, 참여한 뒤 첫 변경은 바로). 이번 참여 뒤 이 방에 쓴 글·댓글도 새 별명으로 → <a href="/grato-docs/features/circles#open-circle">별명 바꾸기</a></li><li>예전 이름으로 남아 있던 글(예: Apple로 가입해 &quot;익명&quot;으로 쓴 글)은 배포 때 1회성 스크립트로 맞춤</li><li>바뀌지 않는 것: 이미 받은 알림, 선정된 질문의 제안자 이름, 차단 목록의 별명 → <a href="/grato-docs/decisions#adr-22">결정 기록 #22</a></li></ul><h2 id="release-circle-copy" tabindex="-1">2026-10-16 — Circle 문구 다듬기 (2026-10-17 배포) <a class="header-anchor" href="#release-circle-copy" aria-label="Permalink to &quot;2026-10-16 — Circle 문구 다듬기 (2026-10-17 배포) {#release-circle-copy}&quot;">​</a></h2><ul><li>Circle에 공유·링크로 공개하기 전 안내를 &quot;다른 사람에게 불쾌감을 주거나 사생활이 드러나는 내용은 없는지 한 번 더 살펴봐 주세요&quot;로 바꿈(&quot;건강·종교&quot; 예시는 처리방침 7항에만)</li><li>Circle 설정: &quot;위험 작업&quot; → <strong>&quot;주의해 주세요&quot;</strong>, &quot;Circle 탈퇴&quot; → <strong>&quot;Circle 나가기&quot;</strong>(확인 창도 &quot;나가기&quot;)</li><li>모두의 감사방 설정: 긴 설명 대신 짧은 태그(이름·사진 대신 별명 / 누구나 참여 / 멤버 목록 비공개 / 별명은 7일에 한 번 변경), 방 자체를 신고하는 버튼 없앰(운영자가 운영하는 방. 글·댓글·사람 신고는 그대로)</li><li>모두의 감사방 참여 안내 &quot;글은 지금처럼 나만 보기로 저장되고, 글마다 이 방에 나눌지 골라요&quot;</li></ul><h2 id="release-write-question-prompt" tabindex="-1">2026-10-16 — 쓰기 화면: 직접 작성이 처음, 질문은 아래에 (2026-10-17 배포) <a class="header-anchor" href="#release-write-question-prompt" aria-label="Permalink to &quot;2026-10-16 — 쓰기 화면: 직접 작성이 처음, 질문은 아래에 (2026-10-17 배포) {#release-write-question-prompt}&quot;">​</a></h2><ul><li>쓰기를 누르면 &quot;어떻게 쓸까요?&quot; 선택 없이 바로 직접 작성 화면. 저장 버튼 아래 &quot;무엇을 쓸지 막막하다면&quot; 카드에 오늘의 질문(위젯과 같은 질문, &quot;다른 질문&quot;으로 바꾸기)과 <strong>[이 질문으로 감사 적기]</strong> → 그 질문으로 질문으로 쓰기 → <a href="/grato-docs/features/gratitudes">작성</a></li><li>&quot;작성 중인 글 이어 쓰기&quot; 카드는 없어짐(직접 작성 화면이 쓰던 내용을 그대로 불러옴)</li><li>홈 빈 화면 &quot;오늘 감사한 순간을 적어보세요. 나만 볼 수 있어요&quot;에서 &quot;기본으로&quot;를 뺌</li><li>분석: 직접 작성의 <code>gratitude_started</code>는 처음 입력할 때, 질문으로 쓰기는 <code>source: &#39;write_page&#39;</code></li></ul><h2 id="release-platform-tracking" tabindex="-1">2026-10-16 — 가입·이용 플랫폼 기록 (2026-10-17 배포) <a class="header-anchor" href="#release-platform-tracking" aria-label="Permalink to &quot;2026-10-16 — 가입·이용 플랫폼 기록 (2026-10-17 배포) {#release-platform-tracking}&quot;">​</a></h2><ul><li>가입할 때 어디서 만들었는지(웹·iOS 앱·Android 앱)를 <code>users.signupPlatform</code>에, 로그인한 적 있는 곳을 <code>users.platforms</code>에 남김. 기능 이용 기록(<code>analyticsEvents</code>)에도 <code>platform</code></li><li>운영 지표에 <strong>가입 경로 · 사용 기기</strong> 추가 → <a href="/grato-docs/operations/metrics#platforms">운영 지표</a>. 이전 가입자는 &quot;모름&quot;, 사용 기기는 다음에 열 때부터 채워짐</li><li>개인정보처리방침 &quot;이용 기록&quot; 항목에 &quot;이용 환경(웹·iOS 앱·Android 앱)&quot;을 적어 둠(이미 수집하던 범위를 분명히 한 것)</li><li>앱은 다음 빌드부터 기록됨</li></ul><h2 id="release-open-circle" tabindex="-1">2026-10-13 — 모두의 감사방: 별명으로 참여하는 공개 Circle (기능 꺼 둠, 2026-10-17 배포) <a class="header-anchor" href="#release-open-circle" aria-label="Permalink to &quot;2026-10-13 — 모두의 감사방: 별명으로 참여하는 공개 Circle (기능 꺼 둠, 2026-10-17 배포) {#release-open-circle}&quot;">​</a></h2><p>운영자가 여는 Circle 하나에 누구나 별명을 정해 참여할 수 있게 하는 코드입니다. <strong>꺼진 채로 배포</strong>되어 운영자가 켜기 전에는 사용자에게 아무것도 보이지 않습니다. → <a href="/grato-docs/features/circles#open-circle">Circle: 모두의 감사방</a>, <a href="/grato-docs/decisions#adr-21">결정 기록 #21</a></p><ul><li>켜지면: Circle 탭에 &quot;모두의 감사방&quot; 카드(이름·설명은 <code>appConfig/openCircle</code>의 사본 — 멤버가 아니면 그룹 문서와 멤버 목록을 읽을 수 없음)와 <strong>[별명 정하고 참여]</strong>. 시트에서 안내(&quot;이 방에서는 내 이름 대신 별명만 보여요&quot;, &quot;신고 처리를 위해 운영자는 작성자를 확인할 수 있어요&quot;, &quot;불쾌한 콘텐츠와 괴롭힘은 무관용 원칙으로 금지해요&quot;)를 보고 이 방에서 쓸 별명(2~12자)을 정해 참여. 초대 코드 없음, 정원 999명, 자동 참여 없음</li><li>이 방의 글·댓글에는 별명과 첫 글자 아바타만(사진 없음). 쓰기 화면에 &quot;별명 &#39;…&#39;(으)로 올라가요&quot;. 내 Circle 목록에 &quot;별명: …&quot;, Circle 설정에는 초대 코드·멤버 목록 대신 내 별명</li><li>별명 규칙: 방 안에서 겹치지 않음(대소문자·띄어쓰기·전각 무시), 전각 문자는 반각으로 저장(&quot;ＨＡ&quot; → &quot;HA&quot;), 욕설·링크·연락처 금지, &quot;운영자&quot;·&quot;공식&quot;·&quot;Grato&quot; 같은 말 금지. 바꿀 수 없고, 나갔다가 다시 참여하면 새로 정함</li><li>이 방의 새 글은 알리지 않음. 공감 알림은 공감한 사람의 별명으로. 이름을 모르는 알림은 &quot;누군가 공감했어요&quot;처럼(전에는 &quot;누군가님이 공감했어요&quot;)</li><li>이 방에서 차단하면 차단한 사용자 화면에 &quot;… · 모두의 감사방 별명&quot;으로(실제 프로필을 찾지 않음). 신고는 평소처럼, 운영자 화면에는 실제 계정이 함께 보임</li><li>나가기·내보내기·계정 삭제 때 별명도 지움. 운영 계정을 삭제하면 방은 관리자 없이 남고 설정 스크립트로 새 관리자를 정함. 방은 앱에서 지울 수 없고(삭제 버튼 없음, <code>deleteCircle</code>·운영자 Circle 삭제 거부) 설정 스크립트 <code>--delete</code>로만. 방 자체에 대한 신고는 &quot;문제 없음&quot;으로만 닫음(관리자인 운영 계정 이용 정지 거부)</li><li>운영 지표: 모두의 감사방은 Circle 수·멤버 수·초대 지표에서 빼고 따로(멤버, 30일에 나눈 사람)</li><li>배포: functions(새 callable <code>joinOpenCircle</code>, 삭제 없음) + firestore 규칙 → hosting. 인덱스 변경 없음. 켜기는 <a href="/grato-docs/operations/deploy#open-circle">운영 계정 → 설정 스크립트 → 처리방침 → <code>--enable</code></a></li></ul><h2 id="release-after-launch" tabindex="-1">2026-10-12 — 출시 뒤 개선: 차단한 사람의 숫자, 동의 화면, 프로필 사진 삭제 (웹·서버 2026-10-12 배포, 마이페이지 정리는 2026-10-17 배포, 앱은 1.0.1) <a class="header-anchor" href="#release-after-launch" aria-label="Permalink to &quot;2026-10-12 — 출시 뒤 개선: 차단한 사람의 숫자, 동의 화면, 프로필 사진 삭제 (웹·서버 2026-10-12 배포, 마이페이지 정리는 2026-10-17 배포, 앱은 1.0.1) {#release-after-launch}&quot;">​</a></h2><p>QA에서 찾은 문제를 고쳤습니다. 웹과 앱에 함께 적용됩니다(앱은 다음 빌드부터).</p><ul><li>차단한 사람이 <strong>숫자에서도</strong> 빠짐: 홈 &quot;오늘 Circle 활동&quot;의 글·리액션 수, 카드의 댓글 수, 카드·글 화면의 리액션 수. 전에는 글과 댓글은 숨겨도 숫자에는 들어갔음</li><li>가입 직후 로그아웃했다가 다시 로그인하거나 앱을 다시 열 때, 이미 동의한 사용자에게 동의 화면이 잠깐 보였다 사라지던 문제</li><li>프로필 수정에서 <strong>사진 삭제</strong>: 사진을 지우고 이름 첫 글자로 돌아감. 올린 사진 파일도 함께 지움 → <a href="/grato-docs/features/account#profile-photo">프로필 사진</a></li><li>자주 묻는 질문 &quot;앱 설치가 필요한가요?&quot;와 감사 일기 소개 글: 웹(PWA)만 설명하던 것을 iPhone App Store 앱도 있다고 고침</li><li>마이페이지를 한 화면으로: &quot;내 Grato · 통계 · 설정&quot; 탭을 없애고 <strong>나의 감사 기록 → 배지 → 내가 제안한 질문 → 설정</strong> 순서로. 내 글 목록은 홈 &quot;내 기록&quot;과 같아서 뺌. 위의 숫자 칸은 캘린더와 겹치는 이번 달·연속일 대신 <strong>Grato · 최대 연속일 · Circle</strong>. 최대 연속일은 서버가 새로 기록(<code>userStats.longestStreak</code>, 예전 기록은 배포 뒤 한 번 채움) → <a href="/grato-docs/features/account#mypage">마이페이지 구성</a></li><li><strong>설정은 별도 페이지로</strong>: 마이페이지 오른쪽 위 톱니 버튼 → 설정(알림, 의견 보내기, 고객 지원, 차단한 사용자, 로그아웃, 계정 삭제). 로그아웃 버튼도 설정 안으로</li><li>프로필 사진 삭제는 사진 왼쪽 위 <strong>X 버튼</strong>으로 (글씨 링크 대신)</li><li>캘린더 카드(나의 감사 기록, 저장 이미지 포함): &quot;기록한 날&quot;과 거의 같은 &quot;이번 달 감사&quot;(글 수) 칸을 빼고, 오른쪽 위에 <strong>기록한 날 · 연속일</strong>(지난달은 최장 연속)을 나란히. 월 이동 화살표는 카드 안의 &quot;2026년 10월&quot; 옆으로 옮겨 월이 한 번만 보이게. 카드 모양도 배지·내가 제안한 질문과 같은 흰 카드(작은 아이콘 + 제목)로 맞춤</li><li>캘린더 이미지 저장: 맨 아래 글자 워터마크 대신 <strong>Grato 로고</strong>(새싹 마크 + Grato)와 &quot;감사를 함께 나누는 공간&quot;</li><li>아래 탭 이름을 한국어로: Home · Write · Circles · My → <strong>홈 · 쓰기 · Circle · 마이</strong> (Circle은 앱 안의 기능 이름이라 그대로)</li><li>운영: 댓글 수를 작성자별로도 셈(<code>commentAuthors</code>). 배포 뒤 예전 글에 한 번 채움 → <a href="/grato-docs/operations/deploy#release-after-launch">배포</a></li></ul><h2 id="release-admin-metrics" tabindex="-1">2026-10-12 — 운영 지표 대시보드 (2026-10-12 배포) <a class="header-anchor" href="#release-admin-metrics" aria-label="Permalink to &quot;2026-10-12 — 운영 지표 대시보드 (2026-10-12 배포) {#release-admin-metrics}&quot;">​</a></h2><p>운영자가 서비스가 잘 쓰이고 있는지 숫자로 볼 수 있게 했습니다. 사용자에게 보이는 변화는 없습니다.</p><ul><li>관리자 분석 화면(<code>/admin/analytics</code>) 맨 위에 <strong>지표</strong>를 더함. &quot;불러오기&quot;를 누르면 새 callable <code>adminMetrics</code>가 서버에서 계산 → <a href="/grato-docs/operations/metrics">운영 지표</a><ul><li>사용자 수, 최근 7·30일 새 가입과 쓴 사람</li><li>다시 쓰는 비율: 최근 12주의 주별 가입자가 가입 다음 날·7일·30일 뒤에도 쓰는지(D1·D7·D30)</li><li>Circle: Circle에 있는 사람, 최근 30일에 Circle에 나눈 사람, Circle 수·멤버 수</li><li>초대: Circle당 초대로 들어온 사람·초대 코드 사용·초대 공유, 초대 열기 → 참여 비율</li><li>운영자 계정은 모든 지표에서 뺌. 날짜는 KST</li></ul></li><li>초대 공유 이벤트(<code>circle_invite_shared</code>)에 Circle ID를 함께 남기고, Circle 설정 화면의 공유·초대 메시지 복사·코드 복사도 기록함(앱은 다음 빌드부터)</li><li>배포: functions(새 callable <code>adminMetrics</code>, 삭제되는 함수 없음) → hosting. 규칙·인덱스 변경 없음</li></ul><h2 id="release-circle-guide" tabindex="-1">2026-10-12 — 모임 리더를 위한 Circle 가이드 페이지 (웹 2026-10-12 배포, 앱은 다음 빌드) <a class="header-anchor" href="#release-circle-guide" aria-label="Permalink to &quot;2026-10-12 — 모임 리더를 위한 Circle 가이드 페이지 (웹 2026-10-12 배포, 앱은 다음 빌드) {#release-circle-guide}&quot;">​</a></h2><ul><li>새 공개 페이지 <a href="https://grato.today/circle-guide" target="_blank" rel="noreferrer">grato.today/circle-guide</a>: 교회 소그룹·목장, 독서모임, 가족, 친구 모임, 팀·동아리, 상담·코칭·수업 모임의 리더를 위한 Circle 안내. Circle이 무엇인지(글은 기본 나만 보기, 글마다 공유 선택), 세 단계 시작법, 리더의 한 주 루틴, 안전 장치(신고·차단·자동 숨김·24시간 검토·만 14세 이상), 자주 묻는 질문(비용, 50명, 초대 코드 30일·50회, 탈퇴·내보내기, 관리자, 글 삭제)</li><li>시작 버튼: 웹에서 로그인하지 않았으면 &quot;웹에서 시작하기&quot;와 App Store 배지(Android 앱은 준비 중 안내), 로그인했거나 앱 안이면 &quot;Circle 만들러 가기&quot;(Circle 탭). 페이지 본문에는 다른 플랫폼 이름을 쓰지 않음(앱에서도 보이는 페이지)</li><li>미리 렌더링(정적 HTML, <code>FAQPage</code> 구조화 데이터)과 sitemap에 추가. 다른 소개 페이지 아래 링크, 자주 묻는 질문에 &quot;우리 모임에서 Circle을 열려면 어떻게 하나요?&quot;, Circle이 하나도 없을 때 Circle 탭에 &quot;모임에서 Circle 쓰는 법 보기&quot; 링크</li><li>앱: grato.today/circle-guide 링크를 누르면 앱 안의 같은 페이지가 열림, Circle 탭 링크도 다음 앱 빌드부터</li></ul><h2 id="release-login-subtitle" tabindex="-1">2026-10-11 — 로그인 화면 안내 문구 정리 (웹 2026-10-12 배포) <a class="header-anchor" href="#release-login-subtitle" aria-label="Permalink to &quot;2026-10-11 — 로그인 화면 안내 문구 정리 (웹 2026-10-12 배포) {#release-login-subtitle}&quot;">​</a></h2><ul><li>로그인 카드의 &quot;이메일, Google 또는 Apple로 로그인하세요&quot; 문구를 뺌. 바로 아래 입력칸과 버튼이 같은 내용을 보여 줌. 회원가입·비밀번호 재설정 화면의 안내 문구는 그대로</li><li>앱에는 다음 앱 빌드부터 반영(웹 배포는 grato.today에만 적용)</li></ul><h2 id="release-app-store-link" tabindex="-1">2026-10-11 — iOS 앱 출시: grato.today에 App Store 안내 (웹 2026-10-11 배포) <a class="header-anchor" href="#release-app-store-link" aria-label="Permalink to &quot;2026-10-11 — iOS 앱 출시: grato.today에 App Store 안내 (웹 2026-10-11 배포) {#release-app-store-link}&quot;">​</a></h2><p>iOS 앱이 App Store에 출시되어 웹에서 앱으로 갈 길을 만들었습니다. Android 앱은 준비 중입니다.</p><ul><li>첫 화면(소개) 아래에 App Store 공식 배지와 &quot;Android 앱은 준비 중이에요&quot;를 보여 줌. <strong>웹에서만</strong> 보이고 앱 안에서는 보이지 않음(이미 앱을 쓰는 중이고, iOS 앱 화면에 다른 플랫폼을 언급하면 심사 가이드라인 2.3.10 위반)</li><li>iPhone Safari로 grato.today의 어느 페이지에 들어와도 상단에 App Store &quot;받기&quot; 배너(Smart App Banner)가 뜸</li><li>회사 사이트 <a href="https://mknw.cc" target="_blank" rel="noreferrer">mknw.cc</a>의 Projects 에 Grato를 올리고 grato.today로 연결</li></ul><h2 id="release-ios-1-0" tabindex="-1">2026-10-12 — iOS 앱 App Store 출시 <a class="header-anchor" href="#release-ios-1-0" aria-label="Permalink to &quot;2026-10-12 — iOS 앱 App Store 출시 {#release-ios-1-0}&quot;">​</a></h2><ul><li><strong>Grato 1.0.0 (빌드 3)이 App Store(한국)에 출시됐습니다.</strong> 연령 등급 16+(한국 15+), 무료</li><li>Android는 Google Play 내부 테스트 중입니다. D-U-N-S 번호를 받아 조직 계정으로 바꾼 뒤 프로덕션에 출시합니다 → <a href="/grato-docs/operations/store-listing#google-play-console">Google Play 입력</a></li></ul><h2 id="release-ugc-1-2" tabindex="-1">2026-10-10 — App Store 심사 1.2 대응 (iOS 빌드 3으로 재제출, 웹 2026-10-10 배포) <a class="header-anchor" href="#release-ugc-1-2" aria-label="Permalink to &quot;2026-10-10 — App Store 심사 1.2 대응 (iOS 빌드 3으로 재제출, 웹 2026-10-10 배포) {#release-ugc-1-2}&quot;">​</a></h2><p>첫 App Store 심사에서 가이드라인 1.2(사용자 생성 콘텐츠)로 반려됐습니다. 필요한 장치(약관 동의, 자동 필터, 신고, 차단, 24시간 처리)는 이미 있었고, 화면에서 더 분명히 보이게 했습니다.</p><ul><li>가입·동의 화면: &quot;이용약관에 동의해요&quot; 바로 아래에 무관용 원칙(불쾌하거나 해로운 콘텐츠와 괴롭힘 금지, 확인되면 삭제·이용 정지)을 보여 줌</li><li>로그인 화면 아래: 만 14세 이상·약관 동의 후 이용, 무관용 원칙 한 줄</li><li>차단 확인 창: &quot;상대에게는 알리지 않고, 운영자에게는 검토를 위해 알려요&quot;</li><li>심사 회신: 실제 기기에서 약관 동의·신고·차단을 보여 주는 화면 녹화 → <a href="/grato-docs/operations/store-listing#review-notes">심사 메모</a></li></ul><h2 id="release-qa-fixes" tabindex="-1">2026-10-09 — 전체 기능 QA 수정 (2026-10-10 배포) <a class="header-anchor" href="#release-qa-fixes" aria-label="Permalink to &quot;2026-10-09 — 전체 기능 QA 수정 (2026-10-10 배포) {#release-qa-fixes}&quot;">​</a></h2><p>QA 계정으로 모든 기능을 점검하고 찾은 문제를 고쳤습니다. 웹과 앱에 함께 적용됩니다.</p><h3 id="circle·댓글" tabindex="-1">Circle·댓글 <a class="header-anchor" href="#circle·댓글" aria-label="Permalink to &quot;Circle·댓글&quot;">​</a></h3><ul><li>오류 문구 끝에 붙던 &quot;[404]&quot; 같은 숫자를 없앰</li><li>초대 링크·코드 복사가 실패하면 그렇다고 알림(전에는 아무 반응 없음)</li><li>한글 입력 중 Enter로 글자를 확정할 때 댓글이 반쯤 전송되던 문제</li><li>로그인하지 않고 초대 링크를 열면 로그인 화면으로 바로 넘어가지 않고 Circle 이름·소개·멤버 수와 &quot;로그인하고 참여하기&quot;를 보여 줌</li><li>Circle 목록의 멤버 수·이름이 최신으로, 댓글은 새로고침 없이 바로 보임</li><li>글을 보고 돌아오면 홈 피드의 스크롤 위치가 그대로</li><li>피드 끝의 마지막 카드가 글쓰기 버튼에 가리지 않음, 긴 Circle 이름이 닫기 버튼과 겹치지 않음, 나간 Circle의 글은 &quot;지난 Circle&quot;, 볼 권한이 없어진 글은 &quot;찾을 수 없어요&quot; 대신 &quot;볼 수 없는 Grato예요&quot;</li></ul><h3 id="개인-기록·계정" tabindex="-1">개인 기록·계정 <a class="header-anchor" href="#개인-기록·계정" aria-label="Permalink to &quot;개인 기록·계정&quot;">​</a></h3><ul><li>프로필 이름 저장이 연결이 불안정할 때 계속 돌던 문제: 8초 안에 끝나지 않으면 화면에 먼저 반영하고 &quot;연결되면 자동으로 저장돼요&quot;라고 알림</li><li>직접 쓰던 글이 다른 화면에 다녀와도 남아 있음(&quot;작성 중인 글 이어 쓰기&quot;)</li><li>없는 주소는 빈 화면 대신 &quot;페이지를 찾을 수 없어요&quot;</li><li>로그인 화면의 안내 문구가 다른 화면에 다녀온 뒤 다시 뜨지 않음, 입력을 고치면 오류 문구가 사라짐, 브라우저 기본 검사 말풍선 대신 앱 문구</li><li>공유 페이지: 공개를 취소하거나 글을 지우면 바로 사라짐(전에는 1분 캐시), 볼 수 없는 공유 글은 &quot;삭제되었거나 공유가 취소되었을 수 있어요&quot;</li><li>캘린더 이미지: 지난달은 &quot;최장 연속&quot;(그 달 안), 이번 달은 &quot;연속일&quot;. 공유 캘린더의 연속 기록은 &quot;현재 연속 기록&quot;으로 표시</li><li>마이페이지 탭이 다른 화면에 다녀와도 유지, 안내 페이지(FAQ 등) 아래가 탭에 가리지 않고 뒤로 가기가 앱 밖으로 나가지 않음</li><li>화면 읽기 프로그램: 아이콘 버튼에 이름, 알림 설정은 스위치, 바텀 시트는 대화상자로 읽힘</li></ul><h3 id="서버" tabindex="-1">서버 <a class="header-anchor" href="#서버" aria-label="Permalink to &quot;서버&quot;">​</a></h3><ul><li><code>shareRenderer</code>: 글·캘린더·배지 공유 페이지 캐시를 <code>private, no-store</code>로 (함수 <code>shareRenderer</code>와 Hosting만 배포, 규칙·인덱스 변경 없음) → <a href="/grato-docs/architecture/cloud-functions#sharerenderer">shareRenderer</a></li></ul><h2 id="release-phase3" tabindex="-1">2026-10 — 3단계: iOS·Android 앱 (진행 중) <a class="header-anchor" href="#release-phase3" aria-label="Permalink to &quot;2026-10 — 3단계: iOS·Android 앱 (진행 중) {#release-phase3}&quot;">​</a></h2><p>Capacitor로 iOS·Android 앱을 만들고 있습니다. 코드와 단위 테스트는 들어갔고, 실제 기기 확인·서버 배포·스토어 제출이 남았습니다. <strong>웹사이트(grato.today)의 화면과 동작은 바뀌지 않습니다.</strong> → <a href="/grato-docs/mobile/">iOS·Android 앱</a>, <a href="/grato-docs/guide/roadmap#phase-3">로드맵 3단계</a></p><h3 id="앱" tabindex="-1">앱 <a class="header-anchor" href="#앱" aria-label="Permalink to &quot;앱&quot;">​</a></h3><ul><li>iOS·Android 앱 프로젝트 (<code>cc.mknw.grato</code>, Capacitor 8.5, iOS는 Swift Package Manager, Android target SDK 36). iPhone 세로 화면, 라이트 모드</li><li><strong>Google·Apple 로그인</strong>을 휴대폰의 로그인 화면으로. 웹과 같은 계정(같은 uid)으로 로그인되고, 로그인 창을 닫으면 오류 없이 그대로. iPhone에서 Apple로 처음 가입하면 Apple이 알려 준 이름을 씀 → <a href="/grato-docs/decisions#adr-17">결정 기록 #17</a></li><li>계정 삭제의 본인 확인도 같은 로그인 화면. Apple 연결 해제 포함</li><li><strong>푸시 알림</strong>: Circle 새 글, 공감, 질문 선정, (운영자) 신고. 앱을 열어 둔 동안에도 표시되고 누르면 그 화면으로. 알림 권한은 버튼을 눌렀을 때만 물음</li><li><strong>매일 감사 알림을 휴대폰이 직접</strong>: 고른 시각(15분 단위)에 인터넷 없이도 오고, 그날 이미 기록했으면 쉼. 앱이 알림을 맡는 동안 서버 알림은 보내지 않아 하루 한 번 → <a href="/grato-docs/decisions#adr-16">결정 기록 #16</a></li><li><strong>초대·공유 링크로 앱 열기</strong> (Universal Links / App Links). 앱 안의 grato.today 링크는 그 화면으로, 다른 사이트는 앱 안 브라우저로</li><li>공유는 휴대폰 공유 시트로, 캘린더 이미지는 공유 시트에서 사진에 저장 가능. 공유·초대 링크는 항상 <code>https://grato.today</code> 주소</li><li>노치·홈 인디케이터를 피하는 화면, 상태 표시줄, 스플래시, 키보드가 올라오면 아래 탭 숨김, Android 뒤로 가기(열린 시트 닫기 → 이전 화면 → 첫 화면에서 앱 나가기)</li><li>앱에서는 PWA 설치 배너와 &quot;앱 내 브라우저&quot; 경고를 보이지 않음</li><li>개발: <code>npm run dev</code>가 로컬 Firebase 에뮬레이터(가짜 프로젝트)에서 돌아 실제 서비스에 닿지 않음. 실제 프로젝트용 개발 서버는 <code>npm run dev:prod</code> → <a href="/grato-docs/decisions#adr-19">결정 기록 #19</a></li><li>고침: iPhone 위젯이 로그인 상태인데도 &quot;로그인하고 감사 기록을 시작해요&quot;로 남던 문제, Circle을 만들면 목록에 같은 Circle이 두 번 보이던 문제</li><li>웹사이트(grato.today) 반영: 아래 디자인·사진·초대 변경은 2026-10-09 Hosting과 <code>shareRenderer</code> 배포로 웹에도 적용됨</li><li><strong>초대가 쉬워짐</strong>: 카카오톡·LINE에서 초대 링크를 열면 휴대폰 브라우저(앱이 있으면 앱)로 바로 넘어가 로그인이 막히지 않음, Circle을 만들면 곧바로 초대하기 카드, 초대 메시지에 초대 코드 포함</li><li>앱: 연속 7일·30일을 기록한 날 스토어 평점 요청(120일에 한 번까지)</li><li><strong>프로필·Circle 사진이 빨리 뜸</strong>: 올릴 때 512px로 줄여 수 MB → 수십 KB, 1년 캐시를 붙여 한 번 받은 사진은 기기에서 바로. 사진 파일은 10MB까지 고를 수 있음(웹에도 적용)</li><li>화면이 흐릿하던 느낌을 정리: 카드에 따뜻한 테두리와 그림자, 카드 안 크림색 칸은 연회색, 옅은 회색 글씨는 한 단계 진하게(웹에도 적용)</li><li>앱 상단의 &quot;Grato&quot; 글자를 로고 글자로, 모든 화면 상단은 새싹 마크 + 제목(본문과 같은 고딕 굵게; 잠시 함렛 세리프를 썼다가 되돌림). 프로필·Circle 사진은 이름 첫 글자를 먼저 보여 주고 사진이 받아지면 부드럽게 바뀜(빈칸에서 갑자기 나타나지 않음, 사진 서버에 미리 연결)</li><li><strong>새 아이콘과 로고</strong>: 한 줄기에서 돋은 두 잎(새싹) 마크와 Fraunces 이탤릭 로고 글자. 홈 상단은 마크와 로고 글자를 나란히. 앱 아이콘·스플래시·로그인 화면·알림 아이콘·위젯·웹 파비콘에 적용하고, 링크를 공유하면 로고가 든 큰 미리보기 이미지가 나옴(웹에도 적용) → <a href="/grato-docs/mobile/#icons">아이콘과 브랜드</a></li><li><strong>홈 화면 위젯</strong> (iOS·Android, iOS 잠금 화면 포함): 연속일, 오늘 기록 여부, 이번 주 기록, 오늘의 질문. 누르면 글쓰기, 질문을 누르면 그 질문으로 &quot;질문으로 쓰기&quot;. 감사 글 내용은 나오지 않음 → <a href="/grato-docs/mobile/#widgets">위젯</a>, <a href="/grato-docs/decisions#adr-18">결정 기록 #18</a></li><li>iPhone: 화면 왼쪽 가장자리에서 밀어 뒤로 가기(다른 iPhone 앱과 같은 제스처). 링크를 길게 눌러도 미리보기가 뜨지 않음</li><li><strong>캘린더 이미지 저장</strong>(웹·앱): 날짜 숫자가 동그라미 아래로 쏠리던 문제를 고침. 화면을 캡처하지 않고 직접 그려 항상 가로 1080px로 선명하게 저장</li></ul><h3 id="서버·운영-2026-10-09-배포" tabindex="-1">서버·운영 (2026-10-09 배포) <a class="header-anchor" href="#서버·운영-2026-10-09-배포" aria-label="Permalink to &quot;서버·운영 (2026-10-09 배포)&quot;">​</a></h3><ul><li><code>sendToUser</code>가 토큰의 <code>platform</code>에 따라 메시지 모양을 고름: 웹은 데이터 전용 그대로, 앱은 <code>notification</code> 페이로드 → <a href="/grato-docs/features/notifications#message-shape">알림: 메시지 모양</a></li><li><code>sendDailyReminder</code>가 앱이 로컬 알림을 맡은 사용자(<code>notificationSettings.dailyReminderChannel == &#39;local&#39;</code>, 14일 안)를 건너뜀</li><li>Hosting: <code>/.well-known/apple-app-site-association</code>, <code>/.well-known/assetlinks.json</code>과 헤더, <code>appAssociation: &quot;NONE&quot;</code></li><li>앱 빌드를 배포하기 전에 함수와 Hosting을 먼저 올리고, iOS 푸시용 APNs 키를 Firebase에 등록해야 함 → <a href="/grato-docs/mobile/#server-first">서버·Hosting 먼저 배포</a>, <a href="/grato-docs/mobile/#apns-key">APNs 키</a> (2026-10-09 완료)</li><li><strong>웹 Apple 로그인 복구</strong>: 2단계 배포 뒤 웹의 &quot;Apple로 계속하기&quot;가 &quot;지금은 이 방법으로 로그인할 수 없어요&quot;로 실패했음. Firebase Apple 공급업체의 OAuth 코드 흐름 구성(Team ID·Key ID·비공개 키)이 빠져 있었고, 웹·Android에는 필수였음. 콘솔 설정으로 해결(코드 변경 없음) → <a href="/grato-docs/operations/deploy#apple-sign-in">Apple 로그인 설정</a></li><li>기반 작업: Firebase JS SDK 10 → 12 (Capacitor 인증 플러그인 요구), Firebase에 iOS·Android 앱 등록</li></ul><h2 id="release-reminder-15min" tabindex="-1">2026-10-08 — 매일 알림 15분 단위 (배포 완료) <a class="header-anchor" href="#release-reminder-15min" aria-label="Permalink to &quot;2026-10-08 — 매일 알림 15분 단위 (배포 완료) {#release-reminder-15min}&quot;">​</a></h2><ul><li>매일 알림 시간을 15분 단위로 고를 수 있음(예: 오후 8시 15분). 서버가 15분마다 그 시각을 고른 사람에게 보냄</li><li>예전에 시 단위로 고른 설정은 그 시 정각에 그대로 감</li><li>앱(3단계)에서는 휴대폰 자체 알림으로 고른 시각에 정확히 띄울 예정 → <a href="/grato-docs/decisions#adr-16">결정 기록 #16</a></li></ul><h2 id="release-phase2" tabindex="-1">2026-10-08 — 2단계: 스토어 필수 기능 (배포 완료) <a class="header-anchor" href="#release-phase2" aria-label="Permalink to &quot;2026-10-08 — 2단계: 스토어 필수 기능 (배포 완료) {#release-phase2}&quot;">​</a></h2><p>앱 스토어 출시에 필요한 기능입니다. 약관·개인정보 처리방침은 2026년 10월 8일부터 시행하며, 기존 사용자는 다음 접속 때 동의 화면을 거칩니다. Apple 로그인은 Apple 개발자 콘솔과 Firebase 콘솔 설정을 마친 뒤 동작합니다. 매일 알림이 정각이 아니라 매시 40분에 가던 문제도 함께 고쳤습니다(스케줄 <code>0 * * * *</code>). → <a href="/grato-docs/operations/deploy#release-phase2">이번 릴리스 배포</a></p><h3 id="로그인과-가입" tabindex="-1">로그인과 가입 <a class="header-anchor" href="#로그인과-가입" aria-label="Permalink to &quot;로그인과 가입&quot;">​</a></h3><ul><li><strong>Apple로 로그인</strong> 추가. &quot;Google로 계속하기&quot;와 같은 크기로 나란히 표시. &quot;이메일 가리기&quot; 주소도 사용 가능 → <a href="/grato-docs/features/account#providers">계정</a></li><li>Apple로 가입하면 이름이 없어 홈에 &quot;이름을 알려주세요&quot; 카드를 보여 줌</li><li><strong>가입할 때 약관 동의와 만 14세 이상 확인</strong>. 이메일 가입 폼에 체크리스트, Google·Apple은 로그인 뒤 동의 화면. 기존 사용자도 다음에 열 때 한 번 동의함 → <a href="/grato-docs/features/account#consent">약관 동의</a></li><li>만 14세 미만이라고 답하면 계정을 지우고 로그아웃</li><li>이용 정지된 계정, 다른 방법으로 이미 가입한 이메일에 대한 안내 문구</li></ul><h3 id="계정-삭제" tabindex="-1">계정 삭제 <a class="header-anchor" href="#계정-삭제" aria-label="Permalink to &quot;계정 삭제&quot;">​</a></h3><ul><li>MyPage › 설정 › <strong>계정 삭제</strong>. 지워지는 것과 남는 것을 먼저 보여 주고, &quot;계정 삭제&quot;를 입력한 뒤 본인 확인(재로그인)을 거쳐 삭제 → <a href="/grato-docs/features/account#deletion">계정 삭제</a>, <a href="/grato-docs/decisions#adr-15">결정 기록 #15</a></li><li>관리하던 Circle은 가장 오래 함께한 멤버에게 넘어가고, 혼자 있던 Circle은 삭제</li><li>Apple 사용자는 Apple 계정과의 연결도 해제</li><li>로그인 없이 볼 수 있는 계정 삭제 안내 페이지(<code>/account-deletion</code>)와 이메일 요청 방법</li></ul><h3 id="신고·차단" tabindex="-1">신고·차단 <a class="header-anchor" href="#신고·차단" aria-label="Permalink to &quot;신고·차단&quot;">​</a></h3><ul><li>글·댓글의 &quot;⋯&quot; 메뉴에서 <strong>신고하기</strong>(사유 7가지, 자세한 내용 선택)와 <strong>차단하기</strong>. Circle 멤버와 Circle도 신고 가능 → <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a>, <a href="/grato-docs/decisions#adr-14">결정 기록 #14</a></li><li>차단하면 그 사람의 글·댓글이 보이지 않고 그 사람 때문에 오는 알림도 오지 않음. MyPage › 설정 › <strong>차단한 사용자</strong>에서 해제</li><li>공개 공유 페이지에 로그인 없이 쓸 수 있는 &quot;신고하기&quot;(이메일)</li><li>욕설·혐오 표현이 든 Circle 글·공개 글·댓글은 <strong>자동으로 숨기고</strong> 운영자가 확인. 작성자에게는 &quot;검토 중이에요&quot;로 보임</li><li>부적절한 Circle 이름은 만들 때 거절, 공개 이름·Circle 이름 변경은 운영자가 확인</li></ul><h3 id="글" tabindex="-1">글 <a class="header-anchor" href="#글" aria-label="Permalink to &quot;글&quot;">​</a></h3><ul><li>내 감사 글 <strong>삭제</strong>. 달린 댓글도 함께 지워지고, 연속일·이번 달 기록 수는 남은 글로 다시 계산. 받은 배지는 유지 → <a href="/grato-docs/features/gratitudes#delete">감사 글: 삭제</a></li><li>Circle에 공유하거나 링크로 공개하기 전에 민감한 내용(건강·종교 등)을 한 번 더 확인하라는 안내</li><li>확인 창을 앱 안의 대화상자로 바꿈(글·댓글 삭제, Circle 설정의 내보내기·탈퇴·삭제 등)</li></ul><h3 id="운영" tabindex="-1">운영 <a class="header-anchor" href="#운영" aria-label="Permalink to &quot;운영&quot;">​</a></h3><ul><li>관리자 페이지 첫 탭 <strong>신고</strong>: 처리 대기·스팸 의심 목록, 대상 미리보기, 숨기기·숨김 해제·삭제·이용 정지·문제 없음. 새 신고는 운영자 기기로 푸시(24시간 안 처리)</li><li>새 callable <code>moderate</code>, <code>deleteAccount</code>. 새 트리거 <code>onGratitudeDeleted</code>, <code>onReportCreated</code>, <code>onBlockCreated</code>, <code>onPublicNameWritten</code>, <code>onCircleNameWritten</code>. 글·댓글 생성 트리거에 자동 숨김, 알림에 차단 반영</li><li>새 컬렉션 <code>reports</code>, <code>users/{uid}/blocks</code>, <code>disabledUsers</code>와 규칙·인덱스·TTL. 글·댓글 생성에 약관 동의 확인, 작성자의 글 삭제 허용</li><li>약관·개인정보 처리방침 전면 개정, 고객지원 페이지(<code>/support</code>). 약관 시행일 등이 비어 있으면 Hosting 배포를 막는 검사</li><li>함수 엔드투엔드 테스트(<code>npm run test:e2e</code>, 에뮬레이터) 추가 → <a href="/grato-docs/operations/testing#e2e">테스트</a></li></ul><h2 id="release-performance" tabindex="-1">2026-10-08 — 로딩 속도 개선 (배포 완료) <a class="header-anchor" href="#release-performance" aria-label="Permalink to &quot;2026-10-08 — 로딩 속도 개선 (배포 완료) {#release-performance}&quot;">​</a></h2><p>로그인과 페이지 이동이 느리다는 문제를 측정한 뒤 고쳤습니다. 수치는 <a href="/grato-docs/architecture/client#performance">클라이언트 › 성능</a>에 있습니다.</p><ul><li><strong>앱이 바로 뜸</strong>: 로그인 확인이 끝나면 곧바로 화면을 그림. 예전에는 프로필 동기화(서버 왕복 6~7번)가 끝날 때까지 &quot;잠시만요...&quot; 화면이었음</li><li>프로필은 로컬 캐시에서 즉시 표시되고, 동기화는 화면이 뜬 뒤 뒤에서 처리(바뀐 것이 없으면 쓰기 없음)</li><li><strong>기기에 데이터 캐시</strong>: 다시 열 때 최근 데이터가 바로 보임. 로그아웃하면 이 기기의 캐시를 지움(공용 기기 보호)</li><li>페이지별로 코드를 나눠 받음. 첫 화면 앱 코드 57KB → 30KB(gzip). 로그인 후 쓸 페이지는 잠시 뒤 미리 받아 둠</li><li>휴대폰·Safari에서 매번 받던 구글 로그인 준비 파일을 시작 경로에서 제외. 데스크톱은 구글 버튼에 마우스를 올릴 때 준비</li><li>글꼴이 첫 화면을 막지 않음. 소개 페이지 주소 끝 <code>/</code> 리다이렉트 제거</li><li>마이페이지: 목록 20개씩, 캘린더는 보고 있는 달만(KST 기준)</li><li>배포 직후 열려 있던 탭은 새 버전으로 한 번 자동 새로고침. 오프라인이면 앱 안에서 안내하고 연결되면 다시 불러옴</li></ul><h2 id="release-questions" tabindex="-1">2026-10-08 — 질문 제안·선정, 개인 기록 기본값 (배포 완료) <a class="header-anchor" href="#release-questions" aria-label="Permalink to &quot;2026-10-08 — 질문 제안·선정, 개인 기록 기본값 (배포 완료) {#release-questions}&quot;">​</a></h2><p>배포 순서가 바뀌었습니다: 함수·규칙·인덱스 → 인덱스 완료 확인 → 기본 질문 시드(<code>seedQuestions</code>) → Hosting. → <a href="/grato-docs/operations/deploy#deploy-order">배포 순서</a>, <a href="/grato-docs/operations/deploy#release-questions">이번 릴리스</a></p><h3 id="작성과-홈" tabindex="-1">작성과 홈 <a class="header-anchor" href="#작성과-홈" aria-label="Permalink to &quot;작성과 홈&quot;">​</a></h3><ul><li>새 감사 글은 기본이 <strong>&quot;나만 보기&quot;</strong>. 작성 화면의 &quot;누가 볼 수 있나요?&quot;에서 &quot;Circle에 공유&quot;와 Circle을 직접 골라야 공유됨 (Circle을 미리 선택하지 않음). 저장 버튼도 &quot;저장하기&quot; / &quot;Circle에 공유하기&quot;로 구분 → <a href="/grato-docs/decisions#adr-12">결정 기록 #12</a></li><li>홈 피드 첫 탭에 <strong>&quot;내 기록&quot;</strong>(기본 탭, Circle이 없어도 있음). 내 글을 실시간으로 보여 주고 &quot;더 보기&quot;로 이어서 읽음</li><li>내 기록과 MyPage 글 목록의 카드에 &quot;나만 보기&quot; / &quot;링크 공개&quot; / Circle 이름 표시</li><li>Circle이 없으면 내 기록과 함께 Circle 만들기·참여 안내 카드 표시 (예전에는 안내만 보였음)</li><li>피드를 불러오지 못하면 &quot;기록이 없어요&quot; 대신 오류와 &quot;다시 시도&quot;를 보여 줌</li><li>&quot;함께하기&quot; 배지를 Circle을 만들거나 참여할 때 받음 (글을 Circle에 공유하지 않아도)</li></ul><h3 id="질문-제안·선정" tabindex="-1">질문 제안·선정 <a class="header-anchor" href="#질문-제안·선정" aria-label="Permalink to &quot;질문 제안·선정&quot;">​</a></h3><ul><li>질문으로 쓰기는 운영자가 선정한 질문을 사용 (기본 질문 40개 + 선정된 사용자 질문). 읽지 못하면 앱 안의 기본 질문으로 대신함. 사용자가 제안해 선정된 질문에는 &quot;💡 이름 #태그님의 질문&quot; 표시 → <a href="/grato-docs/decisions#adr-11">결정 기록 #11</a></li><li>&quot;질문 제안하기&quot;(질문으로 쓰기 화면, MyPage). 하루 5개, 내용 필터(욕설·연락처), 중복 확인. 선정되면 공개 이름이 함께 표시된다는 안내 → <a href="/grato-docs/features/questions">질문 제안과 선정</a></li><li>MyPage &quot;내가 제안한 질문&quot;: 검토 중 / 선정됨 / 반려됨(사유) / 숨김</li><li>처음 선정되면 알림(&quot;제안한 질문이 선정됐어요 🎉&quot;), 선정 수에 따라 배지 3종(첫 질문 선정, 질문 큐레이터, 질문 장인)</li><li>관리자 페이지 &quot;질문&quot; 탭: 상태별 개수, 검토 대기열(오래된 순), 선정(문구·종류 수정 가능)·반려(사유)·숨김·다시 선정. 배지 조건에 &quot;선정된 질문 수&quot; 추가</li></ul><h3 id="운영-1" tabindex="-1">운영 <a class="header-anchor" href="#운영-1" aria-label="Permalink to &quot;운영&quot;">​</a></h3><ul><li>새 callable <code>submitQuestion</code>, <code>reviewQuestion</code>. 새 컬렉션 <code>questions</code>, <code>questionOriginals</code>, <code>questionQuota</code>(TTL), <code>adminAuditLogs</code>(운영자 작업 기록)와 규칙·인덱스</li><li>기본 질문 원본을 <code>src/content/questions.json</code>으로 옮기고, <code>seedQuestions</code> 스크립트로 Firestore에 넣음</li><li>재사용 가능한 내용 필터(<code>utils/contentFilter.ts</code>)</li></ul><h2 id="_2026-10-07-—-1단계-보안·안정화-배포-완료" tabindex="-1">2026-10-07 — 1단계: 보안·안정화 (배포 완료) <a class="header-anchor" href="#_2026-10-07-—-1단계-보안·안정화-배포-완료" aria-label="Permalink to &quot;2026-10-07 — 1단계: 보안·안정화 (배포 완료)&quot;">​</a></h2><p>2026-10-07에 프로덕션에 배포했습니다. 클라이언트·함수·규칙을 함께 배포했고, 이때만 필요한 1회성 작업도 함께 했습니다. → <a href="/grato-docs/operations/deploy#one-time">1회성 작업</a></p><h3 id="circle" tabindex="-1">Circle <a class="header-anchor" href="#circle" aria-label="Permalink to &quot;Circle&quot;">​</a></h3><ul><li>Circle 생성·참여·탈퇴·멤버 내보내기·삭제·초대 코드 재발급을 서버 함수(callable)로 이전</li><li>새 초대 코드는 8자리(헷갈리는 <code>0 O 1 I</code> 제외), 30일 유효, 50회 사용. 기존 6자리 코드도 계속 사용 가능</li><li>Circle당 최대 50명, 사용자당 최대 20개 Circle</li><li>내보낸 멤버는 관리자가 다시 허용하기 전까지 초대 코드로 재참여 불가. Circle 설정에 &quot;내보낸 멤버&quot; 목록과 &quot;다시 허용&quot; 추가</li><li>이미 참여 중인 Circle의 초대 링크를 열면 &quot;이미 참여 중이에요&quot;로 안내</li><li>삭제되었거나 더 이상 속하지 않은 Circle은 목록에서 자동 정리</li><li>오류 메시지를 상황별 한국어 문구로 통일</li></ul><h3 id="프로필" tabindex="-1">프로필 <a class="header-anchor" href="#프로필" aria-label="Permalink to &quot;프로필&quot;">​</a></h3><ul><li>공개 이름(<code>이름 #태그</code>)을 전역에서 유일하게 관리. 같은 이름·태그는 한 사람만 사용</li></ul><h3 id="공유" tabindex="-1">공유 <a class="header-anchor" href="#공유" aria-label="Permalink to &quot;공유&quot;">​</a></h3><ul><li>외부 공유는 작성자가 공개를 선택한 경우에만 내용 표시 (감사 글, 캘린더 월, 배지)</li><li>공개 전 확인 창, 공개 취소 기능. 공유 페이지 캐시를 줄여 1분 안에 반영</li><li>비공개·없는 페이지는 검색엔진 색인 제외(<code>noindex</code>)</li><li>공유 페이지가 항상 최신 앱 화면을 쓰도록 템플릿을 Hosting에서 받아옴</li></ul><h3 id="기록과-배지" tabindex="-1">기록과 배지 <a class="header-anchor" href="#기록과-배지" aria-label="Permalink to &quot;기록과 배지&quot;">​</a></h3><ul><li>연속일·이번 달 기록 수를 서버에서 한국 시간(KST) 기준으로 계산, 중복 집계 방지</li><li>연속일은 오늘이나 어제 기록했을 때만 표시. 글을 쓴 직후 바로 반영되어 보이도록 개선</li><li>댓글 수를 서버에서 관리</li><li>배지 평가를 글 작성 처리 흐름(통계 → 배지 → 알림)에 통합. 감사 글을 공개하면 &#39;공개한 감사 수&#39; 배지 평가</li></ul><h3 id="알림" tabindex="-1">알림 <a class="header-anchor" href="#알림" aria-label="Permalink to &quot;알림&quot;">​</a></h3><ul><li>매일 알림은 그날 이미 감사를 기록한 사용자에게 보내지 않음</li><li>알림 권한은 사용자가 &quot;알림 받기&quot;를 눌렀을 때만 요청. 홈에 닫을 수 있는 알림 안내 카드 추가</li></ul><h3 id="작성" tabindex="-1">작성 <a class="header-anchor" href="#작성" aria-label="Permalink to &quot;작성&quot;">​</a></h3><ul><li>AI 질문 모드를 없애고 &quot;질문으로 쓰기&quot;로 바꿈. 앱에 들어 있는 질문에 1~2개 답하면(두 번째 질문은 건너뛰기 가능) 답변으로 초안을 만들고, 제목을 붙여 다듬은 뒤 저장. 질문이 마음에 들지 않으면 &quot;다른 질문&quot;으로 바꾸기. 작성 내용은 외부 AI 서비스로 보내지 않음</li><li>서버 함수 <code>generateQuestion</code>·<code>generateGratitude</code>를 없애고, 기존 AI 작성 기록(<code>aiSessions</code>, <code>aiUsage</code>, <code>aiCache</code>)은 정리 스크립트로 삭제</li></ul><h3 id="운영-2" tabindex="-1">운영 <a class="header-anchor" href="#운영-2" aria-label="Permalink to &quot;운영&quot;">​</a></h3><ul><li>Cloud Functions 런타임 Node 22, 모든 함수 서울 리전(<code>asia-northeast3</code>)</li><li>서버 로그 컬렉션에 TTL 적용</li><li>보안 규칙 테스트(에뮬레이터), 함수·클라이언트 단위 테스트 추가</li><li>개발 문서 사이트 공개</li></ul><h2 id="_2026-03-—-초기-구축" tabindex="-1">2026-03 — 초기 구축 <a class="header-anchor" href="#_2026-03-—-초기-구축" aria-label="Permalink to &quot;2026-03 — 초기 구축&quot;">​</a></h2><p>웹 서비스 첫 버전을 만들고 <a href="https://grato.today" target="_blank" rel="noreferrer">grato.today</a>에 공개했습니다.</p><h3 id="기본-기능" tabindex="-1">기본 기능 <a class="header-anchor" href="#기본-기능" aria-label="Permalink to &quot;기본 기능&quot;">​</a></h3><ul><li>Google 로그인(커스텀 도메인), 이메일·비밀번호 로그인, 이용약관·개인정보처리방침</li><li>감사 작성: AI 질문 모드(Gemini, Cloud Functions 경유)와 직접 작성 모드, 질문 풀과 AI 응답 캐시</li><li>공개 프로필과 비공개 사용자 정보 분리, 프로필 사진 업로드</li><li>Circle 생성·참여, 초대 링크와 공유 문구, Circle 설정 페이지(정보 수정, 멤버, 탈퇴·삭제)</li><li>홈 피드: Circle별 실시간 피드와 페이지네이션, 긴 글 펼치기</li></ul><h3 id="소통" tabindex="-1">소통 <a class="header-anchor" href="#소통" aria-label="Permalink to &quot;소통&quot;">​</a></h3><ul><li>Slack 스타일 이모지 리액션, 댓글</li><li>FCM 웹 푸시: Circle 새 글·리액션 알림, 매일 알림(시각 선택), 알림 설정</li></ul><h3 id="습관과-기록" tabindex="-1">습관과 기록 <a class="header-anchor" href="#습관과-기록" aria-label="Permalink to &quot;습관과 기록&quot;">​</a></h3><ul><li>홈 데일리 허브: 연속일 카드, 오늘의 Circle 활동</li><li>공유 가능한 월별 캘린더와 PNG 내보내기</li><li>배지 시스템: 자동 부여, 전체 배지 그리드와 상세 시트, 시즌·기간 한정 배지 모델</li></ul><h3 id="공유와-검색" tabindex="-1">공유와 검색 <a class="header-anchor" href="#공유와-검색" aria-label="Permalink to &quot;공유와 검색&quot;">​</a></h3><ul><li>감사 글·캘린더·배지 공유 페이지와 링크 미리보기(OG 메타)</li><li>SEO 랜딩 페이지(Grato 소개, 감사 일기, 감사의 효과, FAQ)</li></ul><h3 id="운영과-품질" tabindex="-1">운영과 품질 <a class="header-anchor" href="#운영과-품질" aria-label="Permalink to &quot;운영과 품질&quot;">​</a></h3><ul><li>관리자 페이지(배지 관리), 피드백 접수, 분석 이벤트 대시보드</li><li>PWA 설치 배너, 모바일 화면(헤더, 하단 내비게이션, safe area) 정비</li><li>카카오톡 등 인앱 브라우저에서의 로그인 안내</li><li>오류 경계(Error Boundary), 번들 분할, 인덱스 정비</li></ul>',126))]))}});export{f as __pageData,m as default};
